(window.__BOOKS=window.__BOOKS||{})["e_iphtaur"]={"b":[["sd","(«<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>-жрица»)"],["h2","Действующие лица"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span></span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"orest\">Орест</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"pilad\">Пилад</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Хор из 15 гречанок, пленниц и храмовых служительниц</span>"],["person","<span class=\"pn\">Пастух</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\"><span class=\"ch\" data-ch=\"foant\">Фоант</span></span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Вестник</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Афина</span> <span class=\"act-no\">(I)</span>"],["place","Действие происходит в Тавриде."],["act","Пролог","a1",""],["sd","Сцена представляет фронтон храма в дорийском стиле, с золоченым карнизом. Храм расположен на морском берегу. Перед средней дверью, ведущей в святилище и закрытой, высокий алтарь Артемиды, с зубчатыми краями. Алтарь замазан кровью, а по его зубцам развешены остатки вооружения приносимых в жертву эллинов. Из двери направо выходит <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>. Чуть брезжит рассвет."],["scene","Явление первое","s1",1,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Лихих коней владельцу Эномай,<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,1,0,0],["v","Элиды царь, Пелону Танталиду",0,1,0,0],["v","Когда-то отдал дочь. Произошел<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,1,0,0],["v","Атрей от их союза. Агамемнон",0,1,0,0],["v","И Менелай Атреем рождены,",0,2,0,0],["v","И первого я дочь — <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>.",0,3,0,0],["v","Близ быстропенных вод меня отец",0,4,0,0],["v","В ущелии прославленной Авлиды,",0,5,0,0],["v","Где, ярости покорствуя ветров,",0,6,0,0],["v","Весь день Еврип чернеющие волны<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,7,0,0],["v","Катает и кружит, — богине в дар",0,8,0,0],["v","Из-за Елены заколол, оплакав.",0,9,0,0],["v","Он тысячу ахейских кораблей",0,10,1,1],["v","Туда собрал пред этим, и душою",0,10,0,0],["v","Горел добыть для родины — венцов",0,11,0,0],["v","Блистательных, для Менелая ж — мести",0,12,0,0],["v","За брак его поруганный. Но бог",0,13,0,0],["v","Безветрием сковал их, — и, гадая,",0,14,0,0],["v","Так говорил по пламени Калхант:",0,15,0,0],["v","\"Вождь эллинской дружины, Агамемнон,",0,15,0,0],["v","Не тронутся ахейские суда,",0,16,0,0],["v","Пока ты дочь свою, Ифигению,",0,17,0,0],["v","Богине не заколешь. Разве сам",0,18,0,0],["v","Не обещал ты Деве Светозарной",0,19,0,0],["v","Из тех даров, что год тебе родит,",0,20,0,1],["v","Прекраснейшего дара? Клитемнестра",0,20,0,0],["v","В тот год тебе дочь принесла\", — меня",0,21,0,0],["v","Он разумел, — «Ты дочь отдай богине»…",0,22,0,0],["v","И вот на брак с Ахиллом Одиссей",0,23,0,0],["v","От матери увез меня коварно…",0,24,0,0],["v","В Авлиде я — мужами на алтарь",0,25,0,0],["v","Возложена… меч занесен над жертвой,",0,26,0,0],["v","Но волею богини на костре",0,27,0,0],["v","В тот миг меня незримо лань сменила,",0,28,0,0],["v","И через блеск эфирный к берегам",0,29,0,0],["v","Унесена Тавриды. С той поры я",0,30,0,1],["v","Меж варваров живу, где варвар сам",0,30,0,0],["v","Царит <span class=\"ch\" data-ch=\"foant\">Фоант</span> (за легкость ног, конечно,",0,31,0,0],["v","Так названный). А вот и старый храм,<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,32,0,0],["v","Где жрицею я стала Артемиды.",0,33,0,0],["v","Обряды здесь в усладу ей, себе ж",0,34,0,0],["v","По имени лишь светлые, я правлю.",0,35,0,0],["v","Печальный труд…",0,36,0,0],["v","Но страх уста сковал",1,36,0,0],["v","Пред дивною. Из старины обычай",0,37,0,0],["v","Меж таврами ведется и теперь:",0,38,0,0],["v","Коль эллин здесь появится, богине",0,39,0,0],["v","Его готовить в жертву я должна.<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,40,0,1],["sd","Пауза. Восход солнца. <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span> обращается к народившемуся на востоке пурпурному солнцу и поднимает к нему тонкие белые руки,"],["v","О блеск небес! Тебе виденье ночи",0,41,1,0],["v","Поведаю я новое. И будь",0,42,0,0],["v","Целителем, коль сон вещает злое.",0,43,0,0],["v","Мне чудилось, что я уже не здесь,",0,44,0,0],["v","А в Аргосе меж девами покоюсь…",0,45,0,0],["v","И вдруг удар подземный… Выбегаю",0,46,0,0],["v","Из терема и вижу, что карниз",0,47,0,0],["v","Обрушился, что крыша вся в обломках,",0,48,0,0],["v","Вся на земле… и будто из колонн",0,49,0,0],["v","Всего одна осталась в нашем доме,",0,50,0,1],["v","И дивно: с капители волоса",0,50,0,0],["v","Сбегают золотистые, и голос",0,51,0,0],["v","Мне слышится оттуда человека.",0,52,0,0],["v","Я ж, верная искусству обряжать",0,52,0,0],["v","На смерть гостей, — колонну орошаю",0,53,0,0],["v","И чту ее и будто горько так",0,54,0,0],["v","Над новою своею жертвой плачу.",0,54,0,0],["v","Прозрачен сон: <span class=\"ch\" data-ch=\"orest\">Ореста</span> больше нет,",0,55,0,0],["v","<span class=\"ch\" data-ch=\"orest\">Ореста</span> я богине посвящала…",0,56,0,0],["v","Колонна в доме — это сын в семье.<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,57,0,1],["sd","Пауза."],["v","Погибшего вдали я возлияньем",0,61,0,1],["v","Хотела бы почтить, но не пойму,",0,61,0,0],["v","Что сделалось с гречанками, которых",0,62,0,0],["v","Мне отдал царь прислуживать… Без них",0,63,0,0],["v","Не обойтись теперь… И в дом богини,",0,64,0,0],["v","Приют священный мой, я ухожу.",0,65,0,0],["sd","(Входит в правые двери.)"],["scene","Явление второе","s2",1,2],["sd","<span class=\"ch\" data-ch=\"orest\">Орест</span> и <span class=\"ch\" data-ch=\"pilad\">Пилад</span>, по-дорожному, в коротких плащах и фетрах, но с длинными мечами, без свиты, крадучись, идут со стороны моря."],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Гляди… Людей-то нет ли на дороге?",0,66,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","И то гляжу, водя кругами взор.",0,67,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не кажется ль тебе, Пилад, что это —",0,68,0,0],["v","Богини дом, куда триеру мы",0,69,0,0],["v","Направили с тобой, покинув Аргос?",0,70,0,1],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Так кажется обоим нам, <span class=\"ch\" data-ch=\"orest\">Орест</span>.",0,71,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","На алтаре следы ахейской крови.",0,72,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Да и карниз от крови порыжел…",0,73,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","указывая на алтарь"],["v","Га… головы пришельцев умерщвленных.<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,74,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Однако глаз тут нужен да и глаз…",0,75,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О Феб! Куда еще, в какие сети",0,76,0,0],["v","Оракул твой завел меня? С тех пор,",0,77,0,0],["v","Как кровь отца я кровью материнской",0,78,0,0],["v","Омыть дерзнул, Эринии за мной",0,79,0,0],["v","Гоняются посменно, и микенский",0,80,0,1],["v","Скитальцу дом заказан. Сколько раз",0,80,0,0],["v","Я огибал мету в бесплодном беге…",0,81,0,0],["v","И вот к тебе воззвал я: \"Где ж конец<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,82,0,0],["v","Страданиям, безумию, иль обруч,",0,83,0,0],["v","Игрушка я? Иль долго мне еще",0,84,0,0],["v","Меж эллинов кружить?\" Тогда к пределам",0,85,0,0],["v","Таврийским ты послал меня, о бог,",0,85,0,0],["v","Где алтари сестры твоей дымятся",0,86,0,0],["v","За статуей богини. Этот храм",0,87,0,0],["v","Ее, с небес упавшую, скрывает…",0,88,0,0],["v","Иль счастьем, или храбростью ее",0,89,0,0],["v","Я должен взять и, пережив опасность,",0,90,0,1],["v","Афинянам святыню подарить.",0,90,0,0],["v","Последнее веленье и последний",0,91,0,0],["v","Пред отдыхом назначенный мне труд…",0,92,0,0],["v","И вот я здесь, твоим словам покорный,",0,93,0,0],["v","Дельфийский бог! Безвестен и суров",0,93,0,0],["v","Пришельцу край… Быть может, ты, товарищ",0,94,0,0],["v","Несчастия, что делать нам, Пилад,",0,95,0,0],["v","Придумаешь? Ограды стен высоки,",0,96,0,0],["v","И лестницу украдкой мудрено",0,96,0,0],["v","Приладить к ним. Иль, чтоб земли священной<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,97,0,0],["v","Коснулись мы, осилить должен лом",0,98,0,0],["v","Обитые тяжелой медью двери…",0,99,0,0],["v","Но если нас застигнут в воротах,",0,100,0,1],["v","Пока мы их ломаем иль пока",0,100,0,0],["v","С стремянкою мы возимся, то смерти",0,101,0,0],["v","Не избежать… Не лучше ли, пока",0,102,0,0],["v","Не поздно, в путь отправиться обратный?",0,102,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Не думай о побеге… Или нам",0,103,0,0],["v","Привычно это дело? Иль веленьем",0,104,0,0],["v","Небесным мы решимся пренебречь?",0,105,0,0],["v","Нет, лучше, храм покинув, в глубь пещеры",0,105,0,0],["v","Сокроемся, куда волною море,",0,106,0,0],["v","Чернея, плещет; только в стороне",0,107,0,0],["v","От корабля, чтобы, увидев мачту,",0,107,0,0],["v","Кто не сказал царю и силой нас",0,108,0,0],["v","Не взяли бы. Когда же око ночи",0,109,0,0],["v","Откроется таинственной, все силы",0,110,0,1],["v","Ума мы напряжем, чтобы святыню",0,111,0,0],["v","Блестящую из храма унести.",0,112,0,0],["v","Смотри, Орест, нельзя ли меж триглифов",0,113,0,0],["v","Просунуться? Кто доблестен, дерзай,",0,114,0,0],["v","Бездействуют лишь слабые и трусы.",0,115,0,0],["v","Избороздить соленый путь веслом",0,116,0,0],["v","И от меты ворочать… нет, товарищ!",0,117,0,0],["sd","(Внимательно обходят ограду храма, тихо разговаривая.)"],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты хорошо сказал. Пойдем искать",0,118,0,0],["v","Убежища… Из-за меня вещанье",0,120,0,1],["v","Священных уст не пропадет… Дерзнем…",0,121,0,0],["v","Для юных сил и тяжесть не помеха.",0,122,0,0],["sd","Уходят к морю."],["sd","Хор приходит со стороны, символизирующей противоположную морю. Девушки подходят молча, и хор в молитвенных позах останавливается в виду алтаря. Сначала немая сцена, затем —"],["scene","Вступительная песнь хора","s3",1,3],["v","Молча молитесь!",0,123,0,0],["v","Сурового моря и Врат",0,124,0,0],["v","Скалистых соседи!",0,125,0,0],["v","А ты, о Латоны дитя,",0,126,0,0],["v","Сетей богиня и гор…",0,127,0,0],["v","О, призри, богиня:",0,128,0,0],["v","Стопою девичьей",0,130,0,1],["v","К подворью священному я,",0,130,0,0],["v","Где золотом блещет карниз",0,131,0,0],["v","Над лесом могучим колонн,",0,132,0,0],["v","Я, чистая, к чистой иду…",0,132,0,0],["v","Я — жрицы твоей рабыня…",0,133,0,0],["v","Раздолье родимых лугов,",0,134,0,0],["v","Где кони пасутся, и башен",0,134,0,0],["v","Красу, и садов",0,135,0,0],["v","Европы тенистых нега,",0,136,0,0],["v","И предков могилы — забыты.",0,136,0,0],["scene","Явление третье","s4",1,4],["sd","Из двери святилища показывается <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span> с небольшой свитой храмовых прислужниц; из них одна несет тяжелый золотой сосуд со смесью, приготовленной для возлияния."],["scene","Коммос","s5",1,5],["sp","Хор"],["dir","обращаясь к <span class=\"ch\" data-ch=\"ifigeniya\">Ифигении</span>"],["v","Вот и я… что тебя заботит?",0,137,0,0],["v","И зовешь, зачем ты зовешь",0,138,0,0],["v","К Артемиде меня, о дева?",0,138,0,0],["v","Дева — дочь вождя, что под Трою",0,139,0,0],["v","Мириады привез пловцов",0,140,0,1],["v","И судов весельных и славных",0,140,0,0],["v","Десять сотен — о дочь Атридов,",0,141,0,0],["v","Славы громкой Атридов?",0,142,2,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Увы мне, увы!",0,143,2,0],["v","Рабыни, туманом",0,144,2,0],["v","Тяжелым увита я слез…",0,145,0,0],["v","Я стонов и воплей смягчить",0,146,0,0],["v","Напевами лиры и музы",0,147,0,0],["v","Искусством не в силах, рабыни…",0,148,0,0],["v","И беды, что сердце сжимали,",0,149,0,0],["v","В надгробную жалобу льются…",0,150,0,1],["v","Я плачу о брате: его",0,151,0,0],["v","Мне ночь, на небе бледнея,",0,152,0,0],["v","Явила умершим…",0,153,2,0],["v","Конец тебе, дом наш, конец",0,154,0,0],["v","И вам, Танталиды… И ужас,",0,155,0,0],["v","И горе, о Аргос, тебе…",0,156,0,0],["v","О, демон! Единственный брат мой",0,157,0,0],["v","Ужели подземным так сладок?",0,158,0,0],["v","В обитель Аида за ним",0,159,0,0],["v","Из кубка умерших, струею",0,160,0,1],["v","Хребет орошая земли,",0,161,0,0],["v","Что ж медлю свершить возлиянье?",0,162,0,0],["v","Источник горных телиц,",0,163,0,0],["v","И Вакхову сладкую влагу,",0,164,0,0],["v","И труд золотистой пчелы",0,165,0,0],["v","Пролить в усладу для мертвых?",0,166,0,0],["sd","(К одной из прислужниц.)"],["v","Подай мне кубок золотой",0,167,0,0],["v","И влагу пенную Аида.",0,168,0,0],["sd","(Делает возлияние.)"],["v","Ты же, во мраке цветущий",0,170,0,1],["v","Сын Агамемнона, слушай —",0,171,0,0],["v","Тени твоей это дар…",0,172,0,0],["v","Мне на могилу твою",0,173,0,0],["v","С жаркой слезой не дано",0,174,0,0],["v","Локон нести золотой.",0,175,0,0],["v","Аргос священный далеко,",0,176,0,0],["v","И на родимой земле",0,177,0,0],["v","Тенью кровавой живу я.",0,178,0,0],["sp","Хор"],["v","Как эхо тебе отзовусь я",0,179,0,0],["v","Напевом азийским, царевна…",0,180,0,1],["v","Мила надгробная песнь",0,180,0,0],["v","Почившим, и сладко она",0,181,0,0],["v","В мрак ночи подземной для них,",0,182,0,0],["v","С пеаном несхожая, льется…",0,183,0,0],["v","Увы, увы! Атридова дома повержен",0,184,0,0],["v","Сияющий скипетр. Увы!",0,185,0,0],["v","И отчего дома",0,186,2,0],["v","Очаг догорел…",0,187,2,0],["v","Скажи, с кого из блаженных",0,188,0,0],["v","Аргосских царей это зло,",0,189,0,0],["v","Царевна, растет?..",0,190,2,1],["v","С Пелопа ль, когда, на летучих",0,190,0,0],["v","Своих колесницах кружа,",0,191,0,0],["v","Он тестя осилил",0,192,2,0],["v","И в волны низвергнул Миртила,<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a>",0,193,0,0],["v","Начало ужаснейших зол?",0,194,0,0],["v","То Гелия яркое око<a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,195,0,0],["v","Покинуло путь вековой…",0,195,0,0],["v","И вот по чертогам,",0,196,2,0],["v","Вслед за руном золотым,",0,197,0,0],["v","Убитых печальная цепь",0,198,0,0],["v","И цепь потянулась несчастий.",0,199,0,0],["v","И кара за кровь Танталидов,",0,200,0,1],["v","Поверженных раньше, не хочет",0,200,0,0],["v","Покинуть чертога — и демон",0,201,0,0],["v","С тех пор на тебя, о царевна,",0,202,0,0],["v","Злой яростью пышет…",0,202,2,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Мне демон недобрый на долю",0,203,0,0],["v","Достался, и, пояс девичий",0,204,0,0],["v","Спуская, меня обрекла",0,205,0,0],["v","Родимая мукам… В ту ночь —",0,205,0,0],["v","Суровую выпряли Парки<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,206,0,0],["v","Мне первую нить.",0,207,2,0],["v","На то ли в чертоге своем",0,207,0,0],["v","Весеннюю розу —",0,208,2,0],["v","Меж эллинских дев",0,209,0,0],["v","Когда-то сиявшая Леды",0,210,0,1],["v","Злосчастная дочь",0,210,0,0],["v","Носила меня и растила,",0,211,0,0],["v","Чтоб грустную жертву обета",0,212,0,0],["v","Под нож нечестивый отдать",0,213,0,0],["v","Отцовский, ребенка?",0,213,2,0],["v","О, горе, о, горе! Зачем",0,214,0,0],["v","К песчаным наносам Авлиды",0,215,0,0],["v","Меня колесница влачила,",0,216,0,0],["v","Невесту Аида?",0,216,2,0],["v","Как здесь я живу",0,217,2,0],["v","В печальных садах,",0,218,2,0],["v","У чуждого лютого моря,",0,219,0,0],["v","Без мужа, без сына, без друга,",0,220,0,1],["v","Забытая дальней отчизной?",0,220,0,0],["v","Не Геру Аргосскую арфой",0,221,0,0],["v","Я славлю, — и песню челнок",0,221,0,0],["v","У ткацкого стана другим",0,222,0,0],["v","Поет, когда образ выводят",0,223,0,0],["v","Паллады искусно они,",0,223,0,0],["v","А подле — титанов. Увы!",0,224,0,0],["v","Не ризы богини, здесь кровь",0,225,0,0],["v","Гостей, на алтарь пролитая,",0,225,0,0],["v","Узоры выводит; стенанья",0,226,0,0],["v","Тяжелые их — моя песня,",0,226,0,0],["v","Их слезы — мое рукоделье…",0,227,0,0],["v","Но доля суровая жрицы",0,228,2,0],["v","Забыта — я плачу теперь",0,228,0,0],["v","О брате, осиленном смертью",0,229,0,0],["v","В далекой отчизне его…",0,230,0,1],["v","Еще у кормилицы нежной",0,230,0,0],["v","Я дома тогда оставляла",0,231,0,0],["v","Младенчика, нежный цветок…",0,232,0,0],["v","К груди ее сладко прижавшись,",0,233,0,0],["v","У матери спал на руках",0,234,0,0],["v","Аргосского трона наследник.",0,235,0,0],["v","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span> погружается в молитву.<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,235,0,0],["act","Действие первое","a2","I"],["scene","Явление четвертое","s6",2,6],["sd","Те же и пастух со стороны моря. Это человек немолодой, слабого сложения. Он без шапки, видимо, сильно утомленный, взволнованный."],["sp","Корифей"],["v","Покинув брег морской, сюда пастух",0,236,0,0],["v","К тебе идет с какой-то новой вестью.",0,237,0,0],["sp","Пастух"],["dir","ищет глазами <span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span>, потом подходит к ней с поклоном"],["v","Атрида дочь и чадо Клитемнестры,",0,238,0,0],["v","Внемли вестям нежданного гонца.",0,239,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","с неудовольствием поднимая голову"],["v","Чем мысли ты мне хочешь перебить?",0,240,0,1],["sp","Пастух"],["v","Лазурь волны к утесам Симплегады",0,241,0,0],["v","Двух молодых скитальцев принесла:",0,242,0,0],["v","Богине дар отрадный — украшенье",0,243,0,0],["v","Ей на алтарь. Фиалы приготовь,",0,244,0,0],["v","Огонь и меч для освященья жертвы.",0,245,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Скитальцы те откуда же, пастух?",0,246,0,0],["sp","Пастух"],["v","Я эллинов узнал, и только, дева!",0,247,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но их имен ты уловить не мог?",0,248,0,0],["sp","Пастух"],["v","Один из них другого звал <span class=\"ch\" data-ch=\"pilad\">Пиладом</span>.",0,249,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А как <span class=\"ch\" data-ch=\"pilad\">Пилад</span> другого называл?",0,250,0,1],["sp","Пастух"],["v","Не услыхав, кто скажет это, жрица?",0,250,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но как вы их увидели и как,<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,251,0,0],["v","Напав на них, вы ими овладели?",0,252,0,0],["sp","Пастух"],["v","На берегу безлюдных волн морских…",0,253,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А для чего ж вам было море, пастырь?",0,254,0,0],["sp","Пастух"],["v","Мы шли омыть стада росою волн.",0,255,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О, с самого начала… Сердце просит",0,255,0,0],["v","Узнать, как вы могли их захватить.",0,256,0,0],["v","Я способ знать хочу, пастух. Так долго",0,257,0,0],["v","На алтаре божественном у нас",0,258,0,0],["v","Кровь эллинов, алея, не струилась.",0,259,0,0],["sp","Пастух"],["v","Когда меж скал втекающее море",0,260,0,1],["v","Уже принять готовилось стада, —",0,260,0,0],["v","В расселине, прибоем неумолчным",0,261,0,0],["v","Проделанной, где под навесом сбор",0,262,0,0],["v","Пурпуровых улиток происходит,",0,263,0,0],["v","Едва отхлынут волны — наш пастух",0,264,0,0],["v","Двух юношей увидел…",0,265,0,0],["v","Тихо. Тихо",1,265,0,0],["v","Они крались обратно… \"Пастухи, —",0,266,0,0],["v","Он говорит, — там демоны таятся!\"<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,267,0,0],["v","Тут набожный меж нас нашелся. Руки",0,268,0,0],["v","Воздел он и молиться стал безвестным.",0,269,0,0],["v","\"О, дивный сын, — молил он, — Левкофеи,<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,270,0,1],["v","Страж кораблей, владыка Палемон,",0,270,0,0],["v","О, смилуйся над нами! Диоскуры,",0,271,0,0],["v","Коль это вы, иль вы, Переев род,",0,271,0,0],["v","Где пятьдесят сияет сребротелых",0,272,0,0],["v","И дивных нимф…\" Но тут другой пастух,",0,273,0,0],["v","Все бреднями считающий, вмешался",0,273,0,0],["v","И осмеял святошу. \"Вы не верьте,<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,274,0,0],["v","Что боги там, — сказал он, — то пловцы;",0,275,0,0],["v","Корабль у них разбило, а обычай",0,275,0,0],["v","Неласковой страны, быть может, им",0,276,0,0],["v","По слухам уж и раньше был известен,",0,276,0,0],["v","Не тайна же, что Артемиде в дар",0,277,0,0],["v","Гостей мы убиваем\". Большинство",0,278,0,0],["v","Его словам поверило, и тут же",0,278,0,0],["v","Решили мы явленных изловить",0,279,0,0],["v","Для алтаря.",0,280,0,1],["v","Вдруг видим, из скитальцев",1,280,0,0],["v","Один и сам подходит. Головой",0,280,0,0],["v","Так странно стал он потрясать, и стоны",0,281,0,0],["v","Нам тяжкие послышались, а руки",0,281,0,0],["v","От ужаса как будто заходили",0,282,0,0],["v","У странного. Безумствуя, как ловчий,",0,283,0,0],["v","Когда собак сзывает, завопил он:",0,283,0,0],["v","\"Смотри, смотри, <span class=\"ch\" data-ch=\"pilad\">Пилад</span>: исчадье Ада,",0,284,0,0],["v","Змея… А вот вторая… Ай! в меня",0,285,0,0],["v","Нацелились… Гляди… гляди — ехидны",0,285,0,0],["v","Со всех сторон ужасные на ней,",0,286,0,0],["v","И все — в меня!.. О боги, боги! Третья!",0,286,0,0],["v","От риз ее огнем и кровью пышет,",0,287,0,0],["v","Крылатая кружит, и на руках",0,288,0,0],["v","Мать, мать моя у чудища… И ею",0,288,0,0],["v","Она меня сейчас придавит… Ай!..",0,289,0,0],["v","Уже бросает каменную глыбу…",0,290,0,1],["v","Она убьет меня. Куда укрыться?..\"",0,290,0,0],["v","Конечно, вид вещей ему не тем",0,291,1,0],["v","Казался, и мычанье телок наших",0,292,0,0],["v","Да лай собак в уме его больном",0,293,0,0],["v","Стенаньями Эриний отдавались…",0,294,0,0],["v","Припав к земле, мы ожидали смерти,",0,295,0,0],["v","Не разжимая губ… Но вот тяжелый",0,295,0,0],["v","Он обнажает меч… И, точно лев,",0,296,0,0],["v","Бросается… на стадо… Он Эриний",0,297,0,0],["v","Мучительных преследует, но только",0,298,0,0],["v","Телиц бока его железо порет,",0,299,0,0],["v","И пеною кровавою уже",0,300,0,1],["v","Покрылась зыбь залива. Не глядеть же",0,300,0,0],["v","Нам было на разбой. Мы стали к битве",0,301,0,0],["v","Готовиться, я раковину взял",0,302,0,0],["v","И затрубил, чтобы созвать окрестных.",0,302,0,0],["v","Иль рослых мы и молодых гостей",0,303,0,0],["v","Могли б одни осилить, пастушонки?",0,304,0,0],["v","Что мигом тут народу набралось!",0,304,0,0],["v","Но вот глядим — безумья весел буйных",0,305,0,0],["v","И свист и плеск утихли разом, — гость",0,306,0,0],["v","На землю пал, и пеной подбородок",0,306,0,0],["v","Покрылся у недужного. Лицом",0,307,0,0],["v","Нам счастье повернулось — ни одна",0,308,0,0],["v","Свободною на миг не оставалась",0,308,0,0],["v","Из рук, — и град летел в него каменьев.",0,309,0,0],["v","А друг меж тем больному пену с губ",0,310,0,1],["v","Полою утирал и от ударов",0,311,0,0],["v","Его плащом искал загородить,",0,312,0,0],["v","Он о больном заботился так нежно…",0,313,0,0],["v","Глядим, и тот поднялся, уж не бредит;",0,314,1,0],["v","Прибой волны враждебной увидав",0,315,0,0],["v","И тучу зла, нависшую над ними,",0,316,0,0],["v","Он завопил, но камнями в ответ",0,317,0,0],["v","Со всех сторон друзей мы осыпали.",0,318,0,0],["v","И вот призыв грозящий излетел",0,320,0,1],["v","Из уст его: \"<span class=\"ch\" data-ch=\"pilad\">Пилад</span>, коль неизбежно",0,320,0,0],["v","Нам умереть — со славою умрем.",0,321,0,0],["v","Меч из ножен, товарищ!\" Блеск тяжелых",0,322,0,0],["v","Мечей по чаще нас рассеял; но",0,323,0,0],["v","Один бежит, а десять напирают,",0,324,0,0],["v","С каменьями — отгонят тех, и вновь",0,325,0,0],["v","Бежавшие являются и мечут.",0,326,0,0],["v","А веришь ли, из мириады рук",0,327,0,0],["v","Хоть бы одна удачей похвалилась —",0,328,0,0],["v","Добычи нам богиня не дала.",0,329,0,0],["v","Не дерзостью, усердьем мы пришельцев",0,330,0,1],["v","Осилили… их оцепив кольцом",0,330,0,0],["v","Измученным, мы вышибли камнями",0,331,0,0],["v","Мечи из рук, — и преклонить колени",0,332,0,0],["v","Усталость их заставила. К царю",0,333,0,0],["v","Мы пленников доставили, а царь",0,333,0,0],["v","Лишь посмотрел на них — и посылает",0,334,0,0],["v","Тебе для омовения и жертвы.",0,335,0,0],["v","Ты ж у богов, о дева, жертв иных",0,336,0,0],["v","И не проси. Довольно чужестранцев,",0,336,0,0],["v","Которые попались нам, и нож,",0,337,0,0],["v","Что над тобой в Авлиде заносили,",0,338,0,0],["v","Элладою оплаканный, падет…",0,339,0,0],["sp","Корифей"],["v","Ты дивное поведал — кто бы ни был",0,340,0,1],["v","По злым волнам до нас доплывший гость.",0,341,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Веди же их сюда, а остальное",0,342,0,0],["v","Меня одной касается, пастух.",0,343,0,0],["sd","(Отпускает его кивком головы, пастух с поклоном, уходит в сторону моря.)"],["scene","Явление пятое","s7",2,7],["sd","Без пастуха."],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О сердце, ты, как гладь морская, было",0,344,0,0],["v","И ласково, и ясно, и, когда",0,345,0,0],["v","На эллина я налагала руки,",0,346,0,0],["v","Ты плакало… Но сон ожесточил",0,347,0,0],["v","Тебя. <span class=\"ch\" data-ch=\"orest\">Орест</span> не видит больше солнца —",0,348,0,0],["v","И слез моих вам, жертвы, не видать.",0,350,0,1],["v","Какая это истина, подруги,",0,350,0,0],["v","Теперь я поняла, что, кто несчастен,",0,351,0,0],["v","К счастливому всегда жесток, ему",0,352,0,0],["v","За прошлые свои он слезы платит…",0,353,0,0],["sd","Пауза."],["v","Не разобьет же дуновеньем бог",0,354,0,0],["v","Еленину триеру в Симплегадах,",0,355,0,0],["v","Не приведет же жертвой к алтарям",0,355,0,0],["v","Проклятую иль Менелая — разве",0,356,0,0],["v","Не из-за них в Авлиде, как тельцу",0,357,0,0],["v","Алтарному, мне пересекли горло",0,358,0,0],["v","Данайцы и отец, родной отец,",0,359,0,0],["v","Над жертвой нож подъявший? О, увы мне.",0,360,0,1],["v","Забвенье мук нам не дано… С мольбой",0,360,0,0],["v","Не раз тогда я руки простирала",0,361,0,0],["v","К его лицу; цепляясь за колени",0,362,0,0],["v","Отцовские, я говорила:",0,363,0,0],["v","\"О!",0,363,0,0],["v","Отец, мой брак постыден — под твоим ли",0,364,0,0],["v","Мне умирать ножом, когда средь жен",0,365,0,0],["v","Пирует мать. Что делаешь? Чертоги",0,366,0,0],["v","Аргосские нам оглашает флейта…",0,366,0,0],["v","А я, невеста, гибну. Иль Аид",0,367,0,0],["v","Пелеевым, отец, назвался сыном,",0,368,0,0],["v","Который был обещан мне, к кому",0,369,0,0],["v","Меня влекла коварно колесница,",0,370,0,1],["v","Чье ложе крови полно!\"",0,370,0,0],["sd","Пауза."],["v","Помню, я,",1,370,0,0],["v","Лицо закрыв тогда прозрачной тканью,",0,371,0,0],["v","Не смела брата с полу приподнять —",0,372,0,0],["v","Бедняжки больше нет; стыдилась, помню,",0,373,0,0],["v","Поцеловать сестру — меня чертог",0,373,0,0],["v","Пелея ждал. И сколько нежной ласки",0,374,0,0],["v","Я берегла для нового свиданья,",0,375,0,0],["v","До Аргоса.",0,376,0,0],["sd","Пауза."],["v","Орест, коль точно нет",0,376,0,0],["v","Тебя в живых, каких ты благ лишился,",0,377,0,0],["v","Какой удел тебя завидный ждал,",0,378,0,0],["v","Наследника отцовского!",0,379,0,0],["v","О, мудрость!",1,379,0,0],["v","Лукавая богиня! К сердцу желчь",0,380,0,1],["v","Вздымается: убитого коснися,",0,381,0,0],["v","Родильницы иль мертвого — и ты",0,382,0,0],["v","Нечист — от алтаря ее подальше!",0,383,0,0],["v","А человечья кровь самой в усладу…",0,384,0,0],["v","Не может быть, чтоб этот дикий бред",0,385,0,0],["v","Был выношен Латоною и Зевсом",0,386,0,0],["v","Был зачат. Нет, нет, не поверю я,",0,387,0,0],["v","Чтоб угощал богов ребенком Тантал",0,388,0,0],["v","И боги наслаждались. Грубый вкус",0,389,0,0],["v","Перенесли туземцы на богиню…",0,390,0,1],["v","При чем она? Да разве могут быть",0,390,0,0],["v","Порочные среди богов бессмертных?",0,391,0,0],["scene","Первый музыкальный антракт","s8",2,8],["sp","Хор"],["str","Строфа I"],["v","Вы, синие, синие волны,",0,392,0,0],["v","Где с морем сливается море,",0,393,0,0],["v","Где жало аргосской осы<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,394,1,0],["v","Когда-то по лютой пучине",0,395,0,0],["v","К брегам азиатским И<em>о</em>",0,396,1,0],["v","Помчало от пастбищ Европы!",0,397,0,0],["v","О, кто же вы, люди? О, кто вы?",0,398,0,0],["v","Еврота ль зеленый тростник",0,399,1,0],["v","Покинув и светлые воды,",0,400,0,1],["v","Священные ль волны Диркеи",0,400,0,0],["v","Забыв, к нераспаханным нивам<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,401,0,0],["v","Пришли вы, где дочери Дня",0,402,0,0],["v","Пролитая смертными кровь",0,403,1,0],["v","Алтарь орошает обильно",0,404,0,0],["v","И храма колонны кропит?",0,405,1,0],["str","Антистрофа I"],["v","Иль парные весел еловых",0,406,0,0],["v","Удары средь пенья и шума",0,407,0,0],["v","Затем рассекали волну,",0,408,1,0],["v","И парус затем надувался,",0,409,0,0],["v","И двигался быстрый корабль,",0,410,1,1],["v","Чтоб после богатством чертоги",0,411,0,0],["v","Одни пред другими кичились?",0,412,0,0],["v","Средь бедствий надежда мила,",0,413,1,0],["v","Но жажда сердец неутешна",0,414,0,0],["v","У тех, кто, по волнам блуждая,",0,415,0,0],["v","И в варварский город заходит",0,416,0,0],["v","За грузом богатства и славой",0,417,0,0],["v","Кто суетной вечно влеком…",0,418,1,0],["v","Есть люди, что грани не видят",0,419,0,0],["v","Желаньям; но скромный милей.",0,420,1,1],["str","Строфа II"],["v","Как миновала лодка",0,420,0,0],["v","Скалистые ворота,<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",0,421,0,0],["v","Финеевы утесы,",0,422,0,0],["v","С прибоем неусыпным?",0,423,0,0],["v","Пока вдоль берегов",0,424,1,0],["v","Морских она стремилась",0,425,0,0],["v","Средь плесков Амфитриты",0,426,0,0],["v","И пятьдесят вокруг",0,427,1,0],["v","Плясало в хороводе",0,428,0,0],["v","Сребристых Нереид?..",0,429,1,0],["v","И Нота и Зефира",0,430,0,1],["v","Дыханье на корме",0,430,1,0],["v","Колеса рулевые",0,431,0,0],["v","Ворочало со скрипом,",0,432,0,0],["v","Когда на остров горный,",0,433,0,0],["v","От птичьих стай весь белый,",0,434,0,0],["v","Ристалищем Ахилла",0,435,0,0],["v","И славный и прекрасный,",0,435,0,0],["v","Пустым и лютым морем",0,436,0,0],["v","Стремились эти люди?",0,437,1,0],["str","Антистрофа II"],["v","О, если бы моленья",0,438,0,0],["v","Царевнины свершились!",0,439,0,0],["v","О, если б чадо Леды,",0,440,0,1],["v","Елена нам досталась",0,440,0,0],["v","Из Трои и росой",0,441,1,0],["v","Ей локоны кровавой",0,442,0,0],["v","Покрыл бы нож царевны!",0,443,0,0],["v","О, если бы свой долг",0,444,1,0],["v","Спартанка заплатила!",0,445,0,0],["v","Но слаще б весть была,",0,446,1,0],["v","Что это из Эллады",0,447,0,0],["v","Пловец меня из рабства",0,448,0,0],["v","Освободить причалил",0,449,0,0],["v","От горестной неволи…",0,450,0,1],["v","О, если б сны сбылися",0,450,0,0],["v","И мне побыть досталось",0,451,0,0],["v","В моем родимом доме",0,452,0,0],["v","И в городе отцовском",0,453,0,0],["v","Среди подруг и кровных",0,454,0,0],["v","Вкусить усладу гимнов…",0,455,1,0],["act","Действие второе","a3","II"],["sd","Со стороны моря показывается толпа пастухов; впереди ведут связанных <span class=\"ch\" data-ch=\"orest\">Ореста</span> и <span class=\"ch\" data-ch=\"pilad\">Пилада</span>."],["scene","Явление шестое","s9",3,9],["v","Ифигения, Орест, Пилад, пастухи, свита.",0,456,0,0],["sp","Корифей"],["dir","заметив приближение толпы"],["v","Ах… вот они… вот… в наручниках оба…",0,457,0,0],["v","Вот новая жертва богине…",0,458,0,0],["v","Идут… Потише, подруги!",0,459,0,0],["v","Вот к храму подходят они,",0,460,0,1],["v","Эллады славные дети.",0,460,0,0],["v","Нелживые речи вещал",0,461,0,0],["v","Тот пастырь рогатого стада.",0,462,0,0],["sd","(К <span class=\"ch\" data-ch=\"ifigeniya\">Ифигении</span>.)"],["v","А ты, о царевна, прими их,",0,463,0,0],["v","Коль мил обычай таврийский",0,463,0,0],["v","Тебе — не Эллады закон",0,464,0,0],["v","Той жертвы святой бы не назвал.",0,465,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","к хору"],["v","Ну хорошо, довольно…",0,466,0,0],["v","Угодное богине — вот забота",0,466,0,0],["v","Моя и первая…",0,467,0,0],["sd","(К пастухам.)"],["v","Освободите их,",0,468,4,0],["v","Священному не подобают узы…",0,469,0,0],["sd","(Служанкам.)"],["v","А вы идите в храм и приготовьте,",0,470,0,1],["v","Что указует нам на этот раз",0,470,0,0],["v","Обычай… О, увы!..",0,471,0,0],["sd","(К юношам.)"],["v","Кто ваша мать, о гости, что когда-то",0,472,0,0],["v","Носила вас, отец, сестра — коль жребий",0,472,0,0],["v","Вам дал сестру? Каких она теперь",0,473,0,0],["v","Цветущих потеряет братьев, сразу",0,474,0,0],["v","Двоих, и одинокой станет! Да,",0,474,0,0],["v","Узнал ли кто, кому судьба какая",0,475,0,0],["v","Назначена? Решение богов",0,476,0,0],["v","Во мраке крадется, и если зло",0,476,0,0],["v","Готовится кому, оно от взора",0,477,0,0],["v","Завешено. Не различает ум,",0,478,0,0],["v","Куда ведет нас жребий.",0,478,0,0],["v","Но откуда",1,478,0,0],["v","Вы прибыли, несчастные? и долго ль",0,479,0,0],["v","Блуждали вы, покуда в этот край",0,480,0,1],["v","Вас принесло? О, долгая с отчизной",0,480,0,0],["v","Вам предстоит разлука под землей.",0,481,0,0],["sd","(Закрывает руками глаза.)"],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что плачешь ты, иль нам грозящий жребий",0,482,0,0],["v","Ты отягчить задумала, жена?",0,483,0,0],["v","Не знаю, кто ты. Мудрый не захочет,",0,483,0,0],["v","Когда Аид ворота перед ним",0,484,0,0],["v","Уж распахнул, бессильными слезами",0,485,0,0],["v","Мучительный одолевать недуг.",0,486,0,0],["v","Из одного, жена, мы двух несчастий",0,486,0,0],["v","Не сделаем, — и глупыми прослыв,",0,487,0,0],["v","И с жизнию расставшись. И пускай",0,488,0,0],["v","Судьба свое берет. А ты над нами",0,489,0,0],["v","Не причитай, пожалуйста; закон",0,490,0,1],["v","Кровавый ваш нам, женщина, известен.",0,491,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Один из вас <span class=\"ch\" data-ch=\"pilad\">Пиладом</span> назван был —",0,492,0,0],["v","Я слышала, и знать хочу — который?",0,493,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","указывая на <span class=\"ch\" data-ch=\"pilad\">Пилада</span>"],["v","Коль радует узнать тебя — так вот он.",0,494,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Из эллинов; а гражданин какой?",0,495,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что выиграешь, коль узнаешь это?",0,496,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Вы братья? Мать одна носила вас?",0,497,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да, братья мы — сердцами, но не кровью.",0,498,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А ты, скажи, как наречен отцом?",0,499,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Поистине мне имя — Злополучный.",0,500,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я говорю не о судьбе, пловец…",0,501,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что имя вам? Над трупом издеваться?",0,502,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Иль жаль тебе назвать себя, гордец?",0,503,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Меня казни, но имени не трогай.",0,504,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","И родины ты мне не назовешь?",0,505,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я осужден, и в том не вижу пользы.",0,506,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Иль милости я не могу просить?..",0,507,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О, я горжусь отчизной — это Аргос.",0,508,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Не шутишь ты? Ты в Аргосе рожден?",0,509,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я из Микен, жена, когда-то славных.",0,510,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но изгнан ты?.. Иль как ты здесь, скажи…",0,511,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Изгнанник я — и вольный и невольный.",0,512,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Как сладко мне аргосца увидать!",0,515,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Тебе, жена, но не аргосцу сладко.",0,516,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Душа горит… твоих послушать слов.<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,513,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","К ярму беды подвесок? Я не спорю…",0,514,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О Трое мне прославленной скажи…",0,515,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","И снов таких ты не желай, как Троя.",0,516,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ее уж нет, скажи? Взята копьем?",0,517,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да, Трои нет… Молва вам не солгала…",0,520,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","И Менелай Елену получил?",0,521,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","К несчастию… для близкого мне мужа.",0,522,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но где ж она? Мы с ней не разочлись.",0,523,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Спартанцево в чертогах ложе делит.",0,524,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Всей Греции… не мне одной… чума!",0,525,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","И я вкусил от этих сладких браков.",0,526,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но эллины… вернулись ли и как?",0,527,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Один вопрос, и тысяча ответов.",0,528,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Пока ты жив, вестей добыть горю.",0,529,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но разделяй свои вопросы, жрица.<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,530,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Там вещий был Калхант, вернулся он?",0,531,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","В Микенах слух прошел, что будто умер.",0,532,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Хвала богам! Ну, а Лаэртов сын?<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,533,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Все странствует, но жив, судя по слухам.",0,534,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О, пусть бы век Итаки не видал!",0,535,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нет, не кляни! И так неладно дома…",0,536,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Фетиды сын еще живет, скажи?",0,537,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нет, для других справлял он брак в Авлиде.",0,538,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Коварный брак и памятный для жертв…",0,539,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но кто же ты? Тебе близка Эллада.",0,540,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ребенком я для греков умерла.",0,541,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Гречанка ты, и этот жар понятен.",0,542,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","тихо"],["v","А тот стратег, блаженным наречен…",0,543,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Какой? Наш вождь не отличался счастьем.",0,544,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Атреев сын и царь Агамемнон.",0,545,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Такого я не знал… Вообще довольно…",0,546,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О, не таись! Обрадуй вестью, гость!..",0,547,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Погиб… С собой другого увлекая…",0,548,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Погиб? Но как? О, горе, горе мне!",0,549,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты слезы льешь? Иль был тебе он близок?",0,550,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я прежний блеск оплакала его.",0,550,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Женою он зарезан… Вот в чем ужас…",0,551,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Вам слезы, вам: и жертва и палач!",0,552,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но больше уст, жена, я не открою.",0,553,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Один вопрос… Атридова жена?..",0,554,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Схоронена, убитая рожденным…",0,555,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Семья убийц! Чего же сын хотел?",0,556,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","За смерть отца он мести добивался.",0,557,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Увы! Увы!",0,558,1,0],["v","Был праведен, но и ужасен суд…",0,559,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","И праведный судья богами брошен.",0,560,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","робко"],["v","Агамемнон имел еще детей…",0,561,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да, в мире он оставил дочь Электру.",0,562,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А о другой… зарезанной… молчат?",0,563,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что ж говорить? Ведь солнце ей не светит.",0,564,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О горькие! И жрец и жертва-дочь.",0,565,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Из-за кого погибла? Из-за твари.",0,566,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А сын отца зарезанного жив?",0,567,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да… Он везде и он нигде, несчастный.",0,568,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Сон, ты солгал… Прости — ты был ничто…",0,569,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","И демоны, которые за мудрость",0,570,0,1],["v","Прославлены, порою лживей снов.",0,570,0,0],["v","Смятение царит в небесном мире",0,571,0,0],["v","И здесь царит… И тяжело глядеть,",0,572,0,0],["v","Как человек, рассудка не лишенный,",0,573,0,0],["v","Вещаниям поверит и за то",0,574,0,0],["v","В глазах людей неослепленных гибнет…",0,575,0,0],["sp","Корифей"],["v","Увы! Увы! Родившие меня",0,575,0,0],["v","Уж умерли или живут — кто скажет?",0,576,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Послушайте же, гости, знаю речь",0,577,0,0],["v","Полезную для вас я, — хоть, признаться,",0,578,0,0],["v","Придумала ее я для себя…",0,579,0,0],["v","Но уж чего же лучше, если дело",0,580,0,1],["v","Всем по сердцу приходится?",0,581,0,0],["sd","(<span class=\"ch\" data-ch=\"orest\">Оресту</span>.)"],["v","Возьмешься ль",0,582,4,0],["v","Ты, если я спасу тебя, друзьям",0,583,0,0],["v","Письмо свезти аргосским? Написал",0,584,0,0],["v","Мне пленник эти строки, сострадая…",0,585,0,0],["v","Он понимал, что если умирает,<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,586,0,0],["v","То волею богини, по закону.",0,587,0,0],["v","Но до сих пор не удавалось мне",0,588,0,0],["v","Спасти посла, с письмом направив в Аргос.<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,590,0,1],["v","Ты с виду, гость, высокого рожденья…",0,590,0,0],["v","Ты знаешь край, ты с теми же знаком,",0,591,0,0],["v","Что я, людьми… Ну, а награда, гость,",0,592,0,0],["v","Немалая — спасенье за дощечку…",0,593,0,0],["v","А спутник твой, как требует закон,",0,593,0,0],["v","Царящий здесь, с тобой расстаться должен",0,594,0,0],["v","И на алтарь покорной жертвой лечь.",0,595,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Твои слова охотно, чужестранка,",0,596,0,0],["v","Согласием венчаю, но его",0,596,0,0],["sd","(указывая на <span class=\"ch\" data-ch=\"pilad\">Пилада</span>)"],["v","Оставить вам на жертву чересчур",0,597,0,0],["v","Мне тяжело бы было.",0,598,0,0],["v","На триере",1,598,0,0],["v","Средь моря был я капитан; а он —",0,599,0,0],["v","Он — пассажир, который только делит",0,600,0,1],["v","Мои труды. И головою друга",0,600,0,0],["v","За эту жизнь корыстно заплатить",0,601,0,0],["v","Мне, женщина, не позволяет совесть…<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,602,0,0],["v","Мы сделаем иначе: ты отдашь",0,603,0,0],["v","Ему письмо; не беспокойся, в Аргос",0,603,0,0],["v","Он передаст табличку, и твои",0,604,0,0],["v","Уладятся дела. А я останусь",0,605,0,0],["v","Для алтаря… Позорней дела нет,",0,606,0,0],["v","Как в море бед тонуть, оставив друга,",0,606,0,0],["v","Спасаться самому. А для меня",0,607,0,0],["v","Так близок он… И солнце мне не краше…",0,608,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Твой дух высок… И в жилах у тебя",0,609,0,0],["v","Струится кровь от благородной крови.",0,610,0,1],["v","Поистине ты друг. Когда б и тот,",0,610,0,0],["v","Которого судьба мне сохранила,",0,611,0,0],["v","Таким же был!",0,612,0,0],["v","И я ведь не одна",1,612,0,0],["v","Здесь на земле, скитальцы, только брата",0,613,0,0],["v","Не суждено мне видеть. Как решил",0,614,0,0],["v","Ты, гость, тому и быть: с моим посланьем",0,615,0,0],["v","Пошлем его, а ты умрешь, пока",0,615,0,0],["v","Желание в тебе так живо, эллин…",0,616,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но где же жрец и дерзкий мой палач?",0,617,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я — жрица, гость, — я призываю Деву.",0,618,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Печален долг и незавиден твой.",0,619,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Невольнице с царем безумно спорить.<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,620,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","И колешь ты сама мечом мужей?",0,620,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Нет, волосы лишь окроплю тебе я.",0,621,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но палачи? Мне интересно знать…",0,622,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","указывая на храм"],["v","Творящие убийство — за стеною…",0,623,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Куда же прах мой отдадут, скажи?",0,623,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Там есть огонь священный и ущелье.",0,624,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Увы! Зачем похоронить сестре",0,625,0,0],["v","Мой бедный прах вы не даете, боги?..",0,626,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Напрасная мольба, печальный гость,",0,626,0,0],["v","Кто б ни был ты. Твоей сестре, конечно,",0,627,0,0],["v","Иное небо светит. Но тебе",0,628,0,0],["v","Я ни в одной не откажу услуге:",0,629,0,0],["v","Ты в Аргосе родился. Я для гроба",0,630,0,1],["v","Украшу, гость, тебя — златой елей",0,631,0,0],["v","Я разолью тебе на тело, горной",0,632,0,0],["v","Златой пчелы цветочный дар тебе",0,633,0,0],["v","Я на костер пролью рукою щедрой…",0,634,0,0],["v","Но я иду к богине дивной в храм,",0,635,0,0],["v","Письмо возьму… Простимся ж, и не думай,",0,636,0,0],["v","Что зла тебе желаю я. Рабы,",0,637,0,0],["v","Покараульте их — оков не надо.",0,638,0,0],["v","О, я тому, который всех друзей",0,639,0,0],["v","Дороже мне, теперь готовлю радость",0,640,0,1],["v","Нежданную: мое письмо живых",0,641,0,0],["v","Ему вернет, умерших заменяя.",0,642,0,0],["sd","(Уходит в храм.)"],["scene","Явление седьмое","s10",3,10],["sd","Без <span class=\"ch\" data-ch=\"ifigeniya\">Ифигении</span>."],["scene","Коммос","s11",3,11],["sp","Хор"],["dir","<span class=\"ch\" data-ch=\"orest\">Оресту</span>"],["str","Строфа"],["v","Мы жалеем тебя, несчастный!",0,643,0,0],["v","Там водой священной и кровью",0,644,0,0],["v","Окропленье тебе готовят…",0,645,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не горе вам — забава, чужестранки.",0,646,0,0],["sp","Хор"],["dir","<span class=\"ch\" data-ch=\"pilad\">Пиладу</span>"],["str","Антистрофа"],["v","Твой же жребий блажен, о юный:",0,647,0,0],["v","Потому что можешь в отчизну",0,648,0,0],["v","Ты ладью, скиталец, направить…",0,649,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Что счастие, когда теряешь друга?",0,650,0,1],["sp","Хор"],["str","Эпод"],["v","Печальны вы, странствия оба.",0,650,0,0],["v","О, горе мне, горе. О…",0,651,0,0],["v","И гибель оба сулят.",0,652,0,0],["v","Увы! Увы!<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,653,2,0],["v","Которого ж больше оплачу:",0,654,0,0],["v","Тебя ль иль плывущего вдаль?",0,655,0,0],["v","Средь мыслей неясных",0,655,2,0],["v","Колеблется сердце тоскливо.",0,656,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ради богов, не правда ли, что мы",0,657,0,0],["v","Одно и то же чувствуем, товарищ?",0,658,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Я с мыслями еще не соберусь!",0,659,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но кто ж она? Как истая гречанка",0,660,0,1],["v","Про Илион она пытала нас",0,660,0,0],["v","И про возврат ахейцев из-под Трои,",0,661,0,0],["v","Про вещего, что по полету птиц",0,661,0,0],["v","Гадал отцам, и про того, что имя",0,662,0,0],["v","Ахиллово носил; Агамемнона",0,663,0,0],["v","Горела знать судьбу она жены,",0,663,0,0],["v","Детей его — и как о них крушилась!",0,664,0,0],["v","Сомненья нет: она чужая здесь —",0,665,0,0],["v","И Аргос ей отчизна. Для чего бы",0,665,0,0],["v","Иначе ей гонца искать, зачем",0,666,0,0],["v","Расспрашивать и с Аргосом сливаться",0,666,0,0],["v","В желании и счастии зачем?",0,667,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Твои уста меня опередили:",0,668,0,0],["v","Мгновение — и что бы я сказал?",0,668,0,0],["v","Что ж я скажу еще: вот разве только",0,669,0,0],["v","Что бедствия царей кругами в мире",0,670,0,1],["v","Расходятся широко, и кого,",0,670,0,0],["v","Кого они при этом не заденут!",0,671,0,0],["v","Но речь ее коснулась одного…",0,672,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Чего, скажи, и сам поймешь яснее…",0,673,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Чего? Иль знать, что ты убит, и жить —",0,673,0,0],["v","Позором мне не будет? Иль не вместе",0,674,0,0],["v","Мы плавали? Иль страшно смерть делить?",0,675,0,0],["v","Иль в Аргосе мне и в земле Фокидской,",0,676,0,0],["v","Ущельями богатой, не прослыть",0,676,0,0],["v","Предателем твоим, коли узнают,",0,677,0,0],["v","Что я один остался жить, и разве",0,678,0,0],["v","Не скажет чернь — а злые языки<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,679,0,0],["v","Меж черни есть, — что я, недугом дома",0,680,0,1],["v","Обрадован аргосского, на трон",0,680,0,0],["v","Замыслил твой, моей жены наследье?<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,681,0,0],["v","Так вот чего боюсь я и стыжусь.",0,682,0,0],["v","О нет! О нет! С тобою вздох последний",0,683,0,0],["v","И я отдам, царевич, и пускай",0,683,0,0],["v","С тобой меня и режут и сжигают:",0,684,0,0],["v","Я друг — и я укоров не снесу!",0,685,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Поудержи язык! С меня довольно",0,686,0,0],["v","И собственных несчастий — я, судьбе",0,686,0,0],["v","Покорствуя, переношу их тяжесть,",0,687,0,0],["v","Но их нести вдвойне я не согласен.",0,688,0,0],["v","Ты говоришь про горе и позор,",0,689,0,0],["v","И мне в удел ты их даешь, товарищ,",0,690,0,1],["v","Невинного мне обрекая друга…",0,690,0,0],["v","В чем зло, скажи, коль, гневом покорен",0,691,0,0],["v","Богов, я жизнь покину? Но, спокойной",0,692,0,0],["v","И чистою семьей любимый муж,",0,693,0,0],["v","За что же ты погибнешь? Оставайся",0,693,0,0],["v","В живых, Пилад, и от моей сестры,",0,694,0,0],["v","Которую тебе я в жены отдал,",0,695,0,0],["v","Рождай детей; ты славу воскреси",0,696,0,0],["v","Атридову, да не погаснет род",0,696,0,0],["v","Отцовский наш без семени в Элладе…",0,697,0,0],["v","Ты должен жить!.. Вернись под отчий кров.",0,698,0,0],["v","Когда ж к брегам Эллады ты причалишь",0,699,0,0],["v","И в Аргос наш, привольный для коней,",0,700,0,1],["v","Войдешь, Пилад, — тебя я заклинаю",0,701,0,0],["v","Десницею: насыпь могилу мне<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,702,0,0],["v","И памятник поставь, и пусть Электра",0,703,0,0],["v","Слезою гроб и локоном почтит.<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,704,0,0],["v","Смотри ж, не брось сестры моей: безродной",0,705,0,0],["v","Она тебе достанется, Пилад!",0,706,0,0],["v","Прости мне. Друг любимый! Вырастали,",0,707,0,0],["v","Охотились мы вместе, и каких",0,708,0,0],["v","Не выносил со мной ты бед! Прости…",0,710,0,1],["v","Оракул нам солгал, нас Феб искусно",0,710,0,0],["v","Подальше от Эллады заманил,",0,711,0,0],["v","Чтоб не краснеть за прежние вещанья,",0,712,0,0],["v","Тот Феб, которому я отдал жизнь, кого",0,713,0,0],["v","Я слушался, безвольный, убивая",0,714,0,0],["v","Родную мать, — и за кого умру.",0,715,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Могилою почту тебя и ложа",0,716,0,0],["v","Сестры твоей я не предам, а ты,",0,717,0,0],["v","Несчастный друг, ты мне в Аиде будешь",0,718,0,0],["v","Дороже, чем теперь. Но ведь еще",0,719,0,0],["v","Оракулом не предан ты, хоть близок",0,720,0,1],["v","От шеи нож. Бывает и в беде",0,721,0,0],["v","Исход благой, когда судьбе угодно.",0,722,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","вглядываясь в дверь, которая медленно отворяется"],["v","Довольно слов: Феб не поможет мне!",0,723,0,0],["v","Смотри — она идет, и смерть за нею.",0,724,0,0],["scene","Явление восьмое","s12",3,12],["sd","Из средних дверей выходит <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span> в сопровождении нескольких прислужниц, которые несут за нею сосуды с медом, маслом, молоком, белые ткани и ножи."],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","обращаясь к тем слугам, которые ничего не несут"],["v","Идите в дом, вы нужное жрецам",0,725,0,0],["v","Устроите…",0,726,0,0],["sd","(Обращаясь к <span class=\"ch\" data-ch=\"orest\">Оресту</span> и <span class=\"ch\" data-ch=\"pilad\">Пиладу</span>.)"],["v","Вот он, мой складень частый,",0,727,4,0],["v","И вот что я скажу вам, пришлецы:",0,728,0,0],["v","Опасности меняют человека;",0,729,0,0],["v","Пройдет беда — осмелится, глядишь,",0,730,0,1],["v","Уж он не тот. Меня невольный трепет",0,730,0,0],["v","Охватит, как подумаю: а что,",0,731,0,0],["v","Как он, домой вернувшись, о посланье",0,732,0,0],["v","И думать позабудет, мой посол?",0,733,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Чего же хочешь ты? За чем же дело?",0,734,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Пусть клятву даст, что отвезет письмо",0,735,0,0],["v","Друзьям моим, кому велю я, в Аргос.",0,736,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты ж клятву дашь ему тогда в обмен?",0,737,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Что ж отрицать иль утверждать должна я?",0,738,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Велишь живым <span class=\"ch\" data-ch=\"pilad\">Пилада</span> отпустить.",0,739,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но ведь письма иначе б не вручил он…",0,740,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А как царя, скажи, ты убедишь?",0,740,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Что царь!..",0,741,0,0],["v","Посланника я на корабль доставлю…",0,742,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Итак, Пилад, клянись! А ты учи…",0,743,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Скажи: клянусь письмо друзьям доставить.",0,744,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Твоим друзьям вручу твое письмо.",0,745,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я ж сохраню тебя меж скал лазурных.",0,746,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Но кем же ты клянешься из богов?",0,747,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Почет и дом мне давшей Артемидой!",0,748,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","А я тебе царем небес клянусь.",0,749,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А если ты меня обидишь, клятву",0,750,0,1],["v","Свою забыв, тогда чему же быть?",0,750,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Возврата мне тогда не видеть… Если ж",0,751,0,0],["v","Нарушишь ты обет — тогда чему?",0,752,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Тогда ноге следа в земле аргосской",0,753,0,0],["v","Не оставлять, коль не спасу тебя…",0,753,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Постой… Одно мы, кажется, забыли…",0,754,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Благой совет не может опоздать.",0,755,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Из клятвы мы допустим исключенье…",0,756,0,0],["v","А вдруг письмо среди вещей в волнах",0,756,0,0],["v","Исчезнет и спасу я только тело;",0,757,0,0],["v","Иль и тогда обетом связан я?",0,758,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","подумав"],["v","Ты знаешь, что мы сделаем? На случай",0,759,0,0],["v","То, что в строках стоит, тебе из уст",0,760,0,1],["v","Я передам — завет друзьям аргосским.",0,761,0,0],["v","Коль сохранишь ты складень мой, черты",0,762,0,0],["v","Безмолвные поведают… но если",0,763,0,0],["v","В волнах морских дощечка пропадет,",0,764,0,0],["v","Живая речь посла ее заменит.",0,765,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Твои слова хвалю и за тебя",0,766,0,0],["v","И за себя. Но передай, что ж должен",0,767,0,0],["v","Я в Аргосе поведать и кому?",0,768,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","\"К <span class=\"ch\" data-ch=\"orest\">Оресту</span> речь, Агамемнона сыну,",0,769,0,0],["v","Убитая в Авлиде говорит,",0,770,0,1],["v","Живая здесь, не там, Ифигения…\"",0,770,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но где ж она?.. Иль мертвая придет?",0,771,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","не отрываясь от складня"],["v","Она перед тобой… Но ты не должен",0,772,0,0],["v","Перебивать теперь ее слова…",0,773,0,0],["v","\"Доставь меня в отчизну, мой родимый,",0,774,0,0],["v","У варваров не дай окончить дни.",0,775,0,0],["v","Освободи от крови и богини.",0,775,0,0],["v","Мне тягостен почет убийцы, брат…\"",0,776,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Что я скажу, Пилад? Но где ж мы, где мы?",0,777,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","продолжая"],["v","\"А если нет, на дом твой навлеку",0,778,0,0],["v","Проклятье я, Орест!..\" Запомни имя.",0,779,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О, боги…<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,780,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ты богов зовешь, зачем?..",1,780,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Так, низачем… Доканчивай… Другими",0,780,0,0],["v","Я мыслями, царица, занят был…",0,781,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Быть может, он, расспрашивая, будет",0,782,0,0],["v","Сомнения питать, тогда скажи,",0,783,0,0],["v","Что спасена я Артемидой: ланью",0,783,0,0],["v","Меня она сменила и, кинжал",0,784,0,0],["v","Насытивши отцовский, в эту землю",0,785,0,0],["v","Перенесла, спасенную. Стоит",0,786,0,0],["v","Там только то, что я теперь сказала.",0,786,0,0],["v","⟨Передает письмо <span class=\"ch\" data-ch=\"pilad\">Пиладу</span>.⟩",0,787,2,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Заклятие твое не тяжело —",0,788,0,0],["v","Ты в добрый час клялась, и не замедлю",0,789,0,0],["v","Я выполнить обещанное. Вот",0,790,0,1],["sd","(К <span class=\"ch\" data-ch=\"orest\">Оресту</span>, протягивая ему письмо.)"],["v","Возьми, Орест, — тебе сестра послала.",0,791,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","обнимая <span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span>"],["v","Давай письмо… Но мне не до письма…",0,792,0,0],["v","Не на словах хочу вкусить я счастья.",0,793,0,0],["v","О, милая, родная, как, обняв",0,794,0,0],["v","Тебя, рука трепещет… Как боюсь",0,795,0,0],["v","Я диву слов твоих душой отдаться…",0,796,0,0],["sp","Корифей"],["v","Как смеешь ты нечистою рукой",0,797,0,0],["v","Касаться риз священных, чужестранец?",0,798,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","не слушая"],["v","Сестра моя, одним отцом со мной",0,800,0,1],["v","Рожденная Агамемноном, брата",0,800,0,0],["v","Нежданно ты находишь вновь, ужель",0,801,0,0],["v","Ты оттолкнешь его, Ифигения?",0,802,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ты, ты — мой брат? Опомнись, гость…",0,803,0,0],["v","Он в Навплии иль в Аргосе теперь.<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,804,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Там твоего, о горькая, нет брата!",0,805,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ты — дочерью Тиндаровой рожден?",0,806,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Пелопову рожден спартанкой внуку…",0,807,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Легко сказать… Но надо доказать…",0,808,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Спроси про дом тогда меня отцовский.",0,809,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Речь за тобой… я буду проверять…",0,810,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Электрины сначала передам",0,810,0,0],["v","Тебе слова: Атрея и Фиеста",0,811,0,0],["v","Ты, может быть, слыхала старый спор…",0,812,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Из-за руна, быть может, золотого?",0,813,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты их на ткань раздор перенесла.",0,813,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ты моего коснулся речью сердца.",0,814,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Там солнца ход обратный выткан был.",0,815,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Да, этот вид я тонкой нитью ткала.",0,816,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","В Авлиду мать тебе с собой дала",0,816,0,0],["v","Аргосских вод для брачных омовений.",0,817,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","грустно"],["v","Все помню… Брак счастливый у меня",0,818,0,0],["v","Не отнимал моих воспоминаний.",0,819,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ну что ж еще? Иль матери волос",0,820,0,1],["v","Ты локона на память не дарила?",0,820,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Чтоб заменить в пустой могиле дочь…",0,821,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но вот тебе приметы, что своими",0,822,0,0],["v","Глазами я видал, там во дворце",0,823,0,0],["v","Стоит копье старинное… Рукою",0,824,0,0],["v","Его Пелоп когда-то сотрясал…",0,825,0,0],["v","Он добыл им, убивши Эномая,",0,825,0,0],["v","Дочь Гипподамию, и то копье",0,826,0,0],["v","Девичий твой таил в Микенах терем.",0,827,0,0],["scene","Коммос","s13",3,13],["lead","(ВМЕСТО МУЗЫКАЛЬНОГО АНТРАКТА)"],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О милый! Нет милей тебя, о милый!",0,828,0,0],["v","Ты здесь, Орест! Ты — мой… А отчий дом —",0,829,0,0],["v","Он — далеко",0,830,2,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О, ты со мной! А мертвою считают",0,830,0,0],["v","Тебя. Ты плачешь, а лицо твое",0,831,0,0],["v","Все светится улыбкою. Я также",0,832,0,0],["v","Зараз и плачу и смеюсь, как ты!",0,833,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","обнимая брата"],["v","И этого ребенка",0,833,0,0],["v","Я на руках кормилицы оставила,",0,834,0,0],["v","Когда он был еще",0,835,0,0],["v","Дрожащим птенчиком…",0,836,0,0],["v","О, сердце! Но слова",0,836,0,0],["v","Бессильны, чтобы ими",0,837,0,0],["v","Твое я счастье рассказала.",0,838,0,0],["v","Предел чудес… Крылатую мечту",0,839,0,0],["v","Опередила жизнь…",0,840,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","О, если б нас соединило счастье!",0,840,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Подруги, радостью безумною душа",0,841,0,0],["v","Наполнилась. Но страх меня берет,",0,842,0,0],["v","Чтоб он из рук моих",0,843,0,0],["v","Не выпорхнул и в воздухе",0,844,0,0],["v","Виденьем не растаял.",0,845,0,0],["v","О ты, очаг Киклопов, вы, Микены,<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,845,0,0],["v","Родные и любимые!",0,846,0,0],["v","Да даруют вам счастье боги.",0,847,0,0],["v","Вы его, свет дома нашего,",0,848,0,0],["v","Единокровного взрастили и вскормили.",0,849,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Рожденье нас благословило… Жребий",0,850,0,1],["v","Был лют для нас и жизни отравил.",0,851,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","О, я познала это… Бесталанной,",0,852,0,0],["v","Отец, отец несчастный",0,853,0,0],["v","Мне к нежной шее нож приставил…",0,854,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Там не был я, но все я будто вижу.",0,855,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Когда меня, невесту,",0,856,0,0],["v","К Ахиллу на ложе брачное",0,857,0,0],["v","Обманом увлекали — там алтарь",0,858,0,0],["v","Туманом слез окутан был… Увы!",0,860,0,1],["v","Увы! Какое омовенье",0,861,0,0],["v","Меня там ожидало.",0,862,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Я плачу над дерзанием отца!",0,863,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Мне жребий судил",0,864,0,0],["v","Отца с душой не отцовской.",0,865,0,0],["v","Но сколько здесь нитей…",0,866,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А если б ты брата сгубила…",0,867,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","…О, сколько здесь нитей сплелось…",0,868,0,0],["v","Случайностей сколько…",0,869,0,0],["v","О, ужас дерзанья!",0,870,0,1],["v","О, на кого я дерзала,",0,870,0,0],["v","Ты, ты, мой брат, едва ушел",0,871,0,0],["v","От рук моих. Твоею кровью",0,872,0,0],["v","Рука сестры готова обагриться",0,873,0,0],["v","Была… Увы!",0,874,0,0],["v","И что ж? Какой конец?",0,875,0,0],["v","Что ждет тебя? Какой возврат",0,876,0,0],["v","Тебе я приготовлю? Но покуда",0,877,0,0],["v","Скорей, скорей от этого предела,",0,878,0,0],["v","От этой крови, и покуда меч",0,879,0,0],["v","До шеи не коснулся братней…",0,880,0,1],["v","Ты, о сердце бессчастное… тебе,",0,881,0,0],["v","Тебе исход отыскивать…",0,882,0,0],["v","Сухим путем… оставив корабли —",0,883,0,0],["v","Пешком идти… но там",0,884,0,0],["v","Ведь варвары… Там нет дорог…",0,885,0,0],["v","На корабле?.. Но долог путь",0,886,0,0],["v","По голубому морю между скал,",0,890,0,1],["v","Меж их толпы.",0,891,0,0],["v","О, где тот бог, иль смертный,",0,892,0,0],["v","Или иная сила, чтоб исход",0,893,0,0],["v","Они нам показали? И последних",0,894,0,0],["v","Двух отпрысков Атрея кто ж отымет,",0,895,0,0],["v","Освободит?.. О, сжальтесь!.. сжальтесь!..",0,896,0,0],["sp","Корифей"],["v","В страну чудес, за сказочный предел",0,900,0,1],["v","Унесена я, и не слухом — зреньем.",0,900,0,0],["sp","<span class=\"ch\" data-ch=\"pilad\">Пилад</span>"],["v","Природою назначено друзьям,",0,901,0,0],["v","Коль встретятся с друзьями, их объятий",0,902,0,0],["v","Искать. Но не пора ли нам",0,903,0,0],["v","Подумать о ином прекрасном солнце",0,904,0,0],["v","Спасенья, не свиданья, — и не здесь.",0,905,0,0],["v","На варварской земле. Не честь разумным,",0,905,0,0],["v","Свою стезю оставив и забыв,",0,906,0,0],["v","Что дороги порою и минуты,",0,907,0,0],["v","За радостью ничтожною бежать…",0,908,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты хорошо сказал. О нас и жребий",0,909,0,0],["v","Заботится. Но если человек",0,910,0,1],["v","Не дремлет сам, и божество сильнее.",0,911,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Удерживать меня не надо все же,",0,912,0,0],["v","Пока судьбы Электриной не знаю.",0,913,0,0],["v","Оставь меня, Орест, любить моих…",0,914,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["dir","указывая на <span class=\"ch\" data-ch=\"pilad\">Пилада</span>"],["v","Вот муж ее — и суждено им счастье.",0,915,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Откуда ж он, Орест, и чей он сын?",0,916,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Сын Строфия, властителя Фокиды.",0,917,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","По матери Атреевич, наш родич?<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a>",0,918,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Мой родич и единый верный друг…",0,919,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Когда отец убить меня сбирался,",0,920,0,1],["v","Его на свете не было еще.",0,920,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да, не было, и Строфий был бездетен.",0,921,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","к <span class=\"ch\" data-ch=\"pilad\">Пиладу</span>"],["v","Привет тебе, супруг моей сестры!",0,922,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Он спас меня… Он мне не только родич.",0,923,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но как на мать дерзнул ты… Как ты мог…",0,924,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Молчание! Я — мститель был отцовский…",0,925,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А ей-то кто убийство нашептал?",0,926,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Оставь… тебе не подобает слышать!",0,927,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Молчу, Орест… Но Аргос за тобой?",0,928,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Мы изгнаны… Там Менелай на троне.",0,929,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","И гонит он недужный братний род?",0,930,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не он — меня Эринии изгнали.",0,930,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ты в бешенство впадал на берегу",0,931,0,0],["v","И этом, брат?.. Так мне передавали.",0,932,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Не в первый раз, увы! глаза людей",0,933,0,0],["v","В безумии неладного видали.",0,934,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я поняла… Богини мстят за мать.",0,935,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Уста кровавой пеной наполняя.",0,935,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Сюда ж зачем направил ты стопы?",0,936,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Так Феб велел — его оракул дивный.",0,937,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Зачем, Орест? Иль тайна есть и здесь?",0,938,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Нет… корень зол великих знать ты можешь.",0,939,0,0],["v","Когда руками кару совершил",0,940,1,1],["v","На матери деяньем несказанным,",0,940,0,0],["v","Безумной я стопою закружил,",0,941,0,0],["v","Спасаясь от Эриний быстробежных…",0,942,0,0],["v","И долго я блуждал, покуда Феб",0,942,0,0],["v","В Афины не привел меня, богиням",0,943,0,0],["v","Отдать отчет в содеянном. Туда",0,944,0,0],["v","На судьбище священное впервые",0,945,0,0],["v","Когда-то Зевс привел Ареса: бог",0,945,0,0],["v","Злодейственной был кровию запятнан.",0,946,0,0],["v","В священный град пришедшего меня",0,947,0,0],["v","Не принимал никто… Они богам",0,947,0,0],["v","Меня считали, верно, ненавистным.",0,948,0,0],["v","А если стыд был у кого сильней,",0,949,0,0],["v","Чем страх, то мне под тем же кровом только",0,950,0,1],["v","Отдельный стол давали, и, вина",0,950,0,0],["v","Себе налив отдельно в кубки, гости",0,951,0,0],["v","Там молча все сидели на пиру,",0,952,0,0],["v","Чтобы сковать уста мне, и казалось,",0,952,0,0],["v","Что не делю я пира их. Хозяев",0,953,0,0],["v","Разоблачать не стал я, я скорбел",0,954,0,0],["v","В безмолвии, и будто ничего",0,955,0,0],["v","Я странного не замечал. И все же",0,955,0,0],["v","Порой сдержать рыданья я не мог,",0,956,0,0],["v","Когда меня кровь матери душила…",0,957,0,0],["v","И говорят: злосчастие мое",0,957,0,0],["v","В обычае афинском остается",0,958,0,0],["v","С тех самых пор, и празднует народ",0,959,0,0],["v","Священный день «Вместительного кубка».<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,960,0,1],["v","Когда ж на холм Аресов я предстал",0,960,1,0],["v","Пред древнее судилище, я камень",0,961,0,0],["v","Ответчика там занял, а старейшей",0,962,0,0],["v","Из Евменид предложен был другой.",0,963,0,0],["v","Я отвечал и слушал показанья",0,963,0,0],["v","О матереубийстве, и меня",0,964,0,0],["v","В конце концов свидетель Феб спасает…",0,965,0,0],["v","Паллада сосчитала черепки,",0,966,0,0],["v","И поровну их было… Из суда я",0,966,0,0],["v","Оправданным ушел. А из богинь",0,967,0,0],["v","Решение приявшие покорно",0,968,0,0],["v","Близ пастбища теперь имеют храм…<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,969,0,0],["v","Ослушницы ж решения дотоле",0,970,0,1],["v","Бесплодным бегом мучили меня,",0,970,0,0],["v","Пока я вновь земли священной Феба",0,971,0,0],["v","Ногою не коснулся и, пред храмом,",0,972,0,0],["v","Плоть изнурив постом и распростерт,",0,973,0,0],["v","Не поклялся расстаться тут же с жизнью,",0,974,0,0],["v","Коль не спасет меня сгубивший бог.",0,975,0,0],["v","И Феб тогда с треножника златого",0,975,0,0],["v","Златое слово проронил, веля",0,976,0,0],["v","Идти в ваш край и изваянье, неба",0,977,0,0],["v","Прекрасный дар, в Афины водворить.",0,978,0,0],["v","В спасении, которое оракул",0,979,1,0],["v","Нам указал, ждем помощи твоей:",0,980,0,1],["v","Коль идола богини мы добудем,",0,980,0,0],["v","Безумие меня покинет, и",0,981,0,0],["v","На корабле многовесельном в Аргос",0,982,0,0],["v","Я отвезу домой тебя… Спаси ж",0,983,0,0],["v","Отцовский дом, сестра, спасая брата!",0,984,0,0],["v","Нет Пелопидов больше, коль теперь",0,985,0,0],["v","Не завладеть нам дивным изваяньем.",0,985,0,0],["sp","Корифей"],["v","О, страшный гнев богов на вас кипит,",0,986,0,0],["v","Род Тантала кидая средь мучений.",0,987,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Желание увидеть Аргос и",0,988,0,0],["v","С тобой, Орест, увидеться желанье",0,989,0,0],["v","До твоего приезда в сердце жило, —",0,990,0,1],["v","И вот они исполнились… Но мне",0,990,0,0],["v","Уж мало этого: от мук <span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,991,0,0],["v","Освободить горю я и Микен",0,992,0,0],["v","Восстановить поруганную славу.",0,992,0,0],["v","Убийце зло простивши. Удержать",0,993,0,0],["v","От моего <span class=\"ch\" data-ch=\"orest\">Ореста</span> нож сумела б,",0,994,0,0],["v","Конечно, я, и дом спасти, но глаз",0,995,0,0],["v","Я не могу закрыть на гнев богини",0,995,0,0],["v","И царскую грозу. Коль не найдет",0,996,0,0],["v","Он статуи на камне, что скажу я,",0,997,0,0],["v","От смерти как уйду, что в оправданье",0,997,0,0],["v","Придумаю? О, если б удалось",0,998,0,0],["v","Тебе зараз и статую и жрицу",0,999,0,0],["v","На корабле отсюда увезти.",0,1000,0,1],["v","Твой подвиг бы прекрасен был. Но если",0,1000,0,0],["v","Нас разделить придется, я погибла…",0,1001,0,0],["v","Что ж? Ты зато спасешься… Умереть",0,1002,0,0],["v","Я не боюсь, не думай, только б брата",0,1003,0,0],["v","Вернуть домой… Когда уколет смерть",0,1004,0,0],["v","Ахейца, слез уносит он в могилу",0,1005,0,0],["v","Обильный дар… Мы ж, жены, ни по чем.",0,1005,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Убийцей быть сестры?.. О нет, довольно",0,1006,0,0],["v","И матери с <span class=\"ch\" data-ch=\"orest\">Ореста</span>. Я делю",0,1007,0,0],["v","С тобой, сестра, желанья: или вместе",0,1008,0,0],["v","Остаться жить, иль вместе умереть.",0,1009,0,0],["v","Иль лягу здесь я мертвым, но с тобой.",0,1010,0,1],["v","Постой, однако ж. Если б Артемида",0,1011,0,0],["v","Шла против нас, зачем бы Аполлон",0,1012,0,0],["v","Мне приказал перевезти богиню",0,1013,0,0],["v","К Палладе в город крепкий и твое,<a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,1014,0,0],["v","Сестра, лицо увидеть? Эти мысли",0,1015,0,0],["v","В душе сложив, я верю, что вернусь.",0,1016,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но уцелеть, похитив изваянье,",0,1017,0,0],["v","Не так легко… И вера о скалу",0,1018,0,0],["v","Такую разобьется… Что придумать?",0,1020,0,1],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Могли бы мы тирана… порешить.",0,1020,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Что говоришь? Хозяина — пришельцам?",0,1021,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но если риск спасет тебя и нас…",0,1022,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я б не могла… Дивлюсь твоей отваге!",0,1023,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но затаить ты в храме нас могла б?",0,1024,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Чтоб ночи мы дождались и бежали?",0,1025,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Да, вору — ночь, что истине — лучи!",0,1026,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Там стражи есть, и их мы не обманем.",0,1027,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Тогда конец… Последний луч погас.",0,1028,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","неуверенно"],["v","Мне кажется, что есть одна возможность…",0,1029,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Какая? В чем? Не медли — поделись…",0,1030,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","В мой план должно войти твое безумье…",0,1030,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","На выдумки хитрее женщин нет!",0,1031,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я объявлю, что матереубийца",0,1032,0,0],["v","Из Аргоса приехал… то есть ты.",0,1033,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Коль польза есть от этого, несчастий",0,1033,0,0],["v","Былых не жаль <span class=\"ch\" data-ch=\"orest\">Оресту</span> — объявляй.",0,1034,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","И что таких богиня не приемлет.",0,1035,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А почему, я, верно, угадал…",0,1036,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ты осквернен… а наши жертвы чисты.",0,1036,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но статуи нам этим не достать.",0,1037,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я объявлю, что кровь смывает только",0,1038,0,0],["v","Волна морей…",0,1039,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но идол, наша цель,",1,1039,0,0],["v","От этого к ладье не станет ближе.",0,1040,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ты осквернил и идола, скажу.",0,1041,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","А место где ж укажешь? Эти скалы?",0,1042,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Где прикрутил канатом ты ладью…",0,1043,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ты понесешь богиню иль другие?",0,1044,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Нет, я сама… Иначе был бы грех.",0,1045,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но роли я Пиладовой не вижу…",0,1046,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Он осквернен с тобою заодно…",0,1047,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Но царь, скажи, об этом известится?",0,1048,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ужели ж нет? Не скрыться от царя.",0,1049,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Ладья у нас надежная и люди…",0,1050,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я на тебя надеюсь в остальном.",0,1050,0,0],["sd","(Указывая на хор.)"],["v","Вот только бы не выдали нас эти…",0,1051,0,0],["sp","<span class=\"ch\" data-ch=\"orest\">Орест</span>"],["v","Так попроси же их… подбором слов",0,1052,0,0],["v","Поласковей. Разжалобить умеет",0,1053,0,0],["v","Людей жена… Все прочее теперь",0,1054,0,0],["v","Уладиться должно, Ифигения!",0,1055,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","к хору"],["v","О женщины, о милые, на вас",0,1056,0,0],["v","Одних теперь надежда — в вашей власти",0,1057,0,0],["v","Или спасти, иль уничтожить нас,",0,1058,0,0],["v","Отечества лишив, сестры и брата…",0,1059,0,0],["v","С чего начну? Мы, жены, дружный род —",0,1060,0,1],["v","Надежней нет для женщины защиты,",0,1060,0,0],["v","Как женщина ж. Покройте ж мой побег",0,1061,0,0],["v","Молчанием, подруги! Нет прекрасней",0,1062,0,0],["v","Безмолвного союзника… Троих",0,1063,0,0],["v","Вы видите людей, которых жребий",0,1064,0,0],["v","Связал навек: на гибель или жизнь…",0,1065,0,0],["sd","(Входя в толпу женщин.)"],["v","О, если я спасусь, мою разделишь",0,1065,0,0],["v","Ты, верная, удачу… Я тебя",0,1066,0,0],["v","Свезу в Элладу также… Дай коснуться",0,1067,0,0],["v","Твоей руки… А ты — ланиты… Ты",0,1068,0,0],["v","Колени дай обнять. Тебя ж молю я",0,1069,0,0],["v","Любимым человеком, если есть",0,1070,0,1],["v","В дому у вас отец, иль мать, иль дети…",0,1070,0,0],["v","Молчите вы? О, дайте зазвучать",0,1071,0,0],["v","Желанью ли, отказу ль! Нет согласья",0,1072,0,0],["v","У вас, мои подруги, так и я",0,1073,0,0],["v","Погибла, и несчастный брат со мною…",0,1073,0,0],["sp","Корифей"],["v","Царевна, успокойся! О спасенье",0,1074,0,0],["v","Своем ты только думай. Все умрет,",0,1075,0,0],["v","Что слышала я, здесь со мной… а в этом",0,1076,0,0],["v","В свидетели Кронида я беру!",0,1076,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","возвращаясь на сцену"],["v","О, будьте же блаженны! Бог заплатит",0,1077,0,0],["v","За это вам, подруги!",0,1078,0,0],["sd","(<span class=\"ch\" data-ch=\"orest\">Оресту</span> и <span class=\"ch\" data-ch=\"pilad\">Пиладу</span>.)"],["v","Ты ступай",0,1079,4,0],["v","В святилище… и ты… Пора. Властитель",0,1080,0,1],["v","Земли узнать захочет, может быть,",0,1080,0,0],["v","Принесена ли жертва…",0,1081,0,0],["sd","(К святилищу.)"],["v","Ты, царица",0,1081,4,0],["v","Морей, меня из дальнего ущелья",0,1082,0,0],["v","Из-под ножа отцовского в тот день",0,1083,0,0],["v","Унесшая, спаси нас снова, этих",0,1083,0,0],["v","Со мной спаси, богиня…",0,1084,0,0],["sd","(Указывая на <span class=\"ch\" data-ch=\"orest\">Ореста</span> и <span class=\"ch\" data-ch=\"pilad\">Пилада</span>.)"],["v","Да не будут",0,1085,4,0],["v","Через тебя обманчивы уста",0,1085,0,0],["v","Для смертных Аполлона. Подойди же",0,1086,0,0],["v","И променяй таврический предел",0,1086,0,0],["v","На славные Афины. Непристойно",0,1087,0,0],["v","Здесь обитать богине, если стен",0,1088,0,0],["v","Блаженная открыта ей ограда…",0,1088,0,0],["sd","По ее знаку <span class=\"ch\" data-ch=\"orest\">Орест</span> и <span class=\"ch\" data-ch=\"pilad\">Пилад</span> входят в храм. <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span> остается около святилища и во время следующей песни хора молится, а потом входит в святилище."],["scene","Второй музыкальный антракт","s14",3,14],["sp","Хор"],["str","Строфа I"],["v","Алкиона, печальная птица,<a class=\"nr\" href=\"#n-k40\" data-n=\"k40\" aria-label=\"Примечание 40\">40</a>",0,1089,0,0],["v","По суровым утесам моря",0,1090,0,1],["v","Льются звуки твоих элегий:",0,1091,0,0],["v","И понятен язык твоей скорби,",0,1092,0,0],["v","Что о муже ты плачешь, людям…",0,1093,0,0],["v","За тобою, бескрылая птица,",0,1094,0,0],["v","Муки сердца пою я, Эллады",0,1095,0,0],["v","Блеск собраний пою я, богиню,",0,1096,0,0],["v","Что звала моя матерь, рожая,",0,1097,0,0],["v","Я пою, и Кинфийские выси,<a class=\"nr\" href=\"#n-k41\" data-n=\"k41\" aria-label=\"Примечание 41\">41</a>",0,1098,0,0],["v","И над мукой Латоны — тени",0,1099,0,0],["v","Нежнолистой пальмы, и лавра",0,1100,0,1],["v","Темнолистую сень, и ветви",0,1101,0,0],["v","Той оливы священной и древней,",0,1102,0,0],["v","Где на озере круглом Дела",0,1103,0,0],["v","Славит муз своим пеньем лебедь…",0,1104,0,0],["str","Антистрофа I"],["v","Сколько слез из очей выбегало",0,1105,0,0],["v","И купало ланиты жарких,",0,1106,0,0],["v","Когда пали родные стены,",0,1107,0,0],["v","А меня уносили волны",0,1108,0,0],["v","На ладье, среди весел быстрых,",0,1109,0,0],["v","Среди вражьих копий. Рабыней",0,1110,0,0],["v","Я у варвара с чадом Атрида",0,1111,0,0],["v","Алтарям предстою Артемиды,",0,1112,0,0],["v","Орошенным ахейской кровью…",0,1113,0,0],["v","О, зачем, кроме горя, иного",0,1114,0,0],["v","Я была причастна удела?",0,1115,0,0],["v","От несчастий привычный не страждет,",0,1116,0,0],["v","Если муки он только меняет,",0,1117,0,0],["v","Но тому, кто улыбку счастья",0,1120,0,1],["v","Видел, иго судьбы нестерпимо,",0,1120,0,0],["v","Если ветер пахнул суровый…",0,1121,0,0],["str","Строфа II"],["v","Пятьдесят аргосских весел",0,1122,0,0],["v","Повезут тебя, царевна,",0,1123,0,0],["v","К берегам отчизны. Пана",0,1124,1,0],["v","Воском слепленные флейты",0,1125,0,0],["v","Переливом звуков ярких",0,1126,0,0],["v","Придадут матросам силы.",0,1127,1,0],["v","Вещий бог, на семиструнной",0,1128,0,0],["v","Лире вторя песне дивной,",0,1129,0,0],["v","На счастливый брег Афины",0,1130,0,1],["v","Возвращение восславит.",0,1130,0,0],["v","Ты отдашься шуму весел",0,1131,0,0],["v","И покинешь нас, царевна…",0,1132,0,0],["v","Перед мачтою, над килем",0,1133,0,0],["v","Парус, вервию покорный",0,1134,0,0],["v","И дыханьем моря полный,",0,1135,0,0],["v","Повлечет ладью по волнам.",0,1135,0,0],["str","Антистрофа II"],["v","О, зачем нельзя рабыне",0,1136,0,0],["v","Вознестись к стезе той яркой,",0,1137,0,0],["v","Где огнистым шаром Гелий",0,1138,1,0],["v","Рассекает выси неба,",0,1139,0,0],["v","Чтоб над домом ей спуститься?",0,1140,0,1],["v","Отчего мне хороводов",0,1141,1,0],["v","Не дано водить, как прежде,",0,1142,0,0],["v","Там, где девой благородной,",0,1143,0,0],["v","В ожиданье брака, возле",0,1144,0,0],["v","Милой матери цвела я,",0,1145,0,0],["v","Лишь для девичьего круга,",0,1146,0,0],["v","Где одна с другой мы в танцах",0,1147,0,0],["v","И в уборах состязались,",0,1148,0,0],["v","Покидая мать и кудри",0,1150,0,1],["v","Под расшитою фатою",0,1144,0,0],["v","Напуская на ланиты.",0,1137,0,0],["act","Действие третье","a4","III"],["scene","Явление девятое","s15",4,15],["sd","<span class=\"ch\" data-ch=\"foant\">Фоант</span> (с внутренней стороны); почти одновременно с ним <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span> из средней двери со статуей на руках."],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["dir","не видя жрицы"],["v","А где же страж святилища, жена",0,1130,0,0],["v","Аргосская? Успела ли пришельцев",0,1123,0,0],["v","Богине посвятить она, и их",0,1116,0,0],["v","Горели уж тела в священной сени?",0,1109,0,0],["sp","Корифей"],["dir","указывая на входящую <span class=\"ch\" data-ch=\"ifigeniya\">Ифигению</span>"],["v","Вот женщина, о царь, и на твои",0,1102,0,0],["v","Она ясней слова ответить может.",0,1095,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Ба… дочь Атридова… что вижу я?",0,1088,0,0],["v","С недвижного подножья для чего же",0,1081,0,0],["v","Ты статую богини поднимаешь?",0,1074,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","отклоняя приближение царя"],["v","О царь, молю — не далее колонны…",0,1067,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Иль новости у вас, Ифигения?",0,1060,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Чур-чур меня… Богиня, помоги…",0,1061,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Вот странное начало… Объяснися…",0,1062,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Добычу вы не чистую ко мне",0,1063,0,0],["v","Доставили, владыка…",0,1064,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","А почем же",1,1064,0,0],["v","Узнала ты?.. Догадки, может быть…",0,1065,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Нет, статуя, качнувшись, отвернулась.",0,1066,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Сама собой, иль сотряслась земля?",0,1067,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Сама собой — ее смежились веки.",0,1068,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Но отчего ж? Иль грех на жертвах был?",0,1069,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ужасный грех… Иной причины нету…",0,1070,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Иль варвара они у нас убили?",0,1170,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Убили, да… но дома, у себя…",0,1170,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Кого ж, скажи… Сгораю нетерпеньем.",0,1171,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Зарезали вдвоем родную мать…",0,1172,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Феб Аполлон… И варвар не посмел бы…",0,1173,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","В Элладе им все двери заперты.",0,1174,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Вот отчего сняла ты изваянье?",0,1175,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Дыхание небесное с него",0,1175,0,0],["v","Не свеет ли греха прикосновенье…",0,1176,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Доведалась ты как об их вине?",0,1177,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Когда от нас богиня отвернулась,",0,1178,0,0],["v","Я вырвала у них признанье, царь.",0,1179,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Искусны ж вы, гречанки… До всего",0,1180,0,1],["v","Дороетесь…",0,1180,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Пришельцы нас пытались",1,1180,0,0],["v","Приятных слов соблазном уловить.",0,1181,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Из Аргоса какая-нибудь радость?",0,1182,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","По их словам, единственный мой брат,",0,1183,0,0],["v","Орест, — он жив.",0,1184,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","А ты, мол, пощади нас?",1,1184,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Отец и жив, и счастлив, и богат…",0,1185,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Надеюсь, ты перед богиней долга",0,1185,0,0],["v","Не вздумала ж нарушить оттого?",0,1186,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Аргосского ножа я не забыла.",0,1187,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Так как же нам с добычей поступить?",0,1188,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но есть закон… Закон укажет.",0,1189,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Чего же ждать… Вот меч… и вот вода…",0,1190,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я ранее должна омыть нечистых.",0,1190,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Проточною или морской водой?",0,1191,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Грехи с людей смывает только море.",0,1192,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Очистив их, богине угодишь…",0,1193,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","И жрицы долг исполнен будет лучше.",0,1194,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Недалеко ходить… Под самый храм",0,1195,0,0],["v","Подходят волны моря.",0,1195,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["dir","качая головой"],["v","Моря мало…",1,1195,0,0],["v","Уединение нам нужно для других",0,1196,0,0],["v","Обрядов, царь…",0,1197,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","По мне, куда угодно",1,1197,0,0],["v","Гостей веди… Не любопытен я…",0,1198,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но статую очистить тоже надо…",0,1199,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Иль матери ее пятнает кровь",0,1200,0,1],["v","Зарезанной?",0,1200,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Коснулась бы иначе",1,1200,0,0],["v","До идола я, царь?",0,1201,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Хвала ж тебе",1,1201,0,0],["v","За набожность и осторожность, дева.",0,1202,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Знаешь, что теперь ты сделай?",0,1203,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Объясни, так буду знать.",1,1203,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Прикажи сковать ахейцев…",0,1204,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Да куда же им бежать?",1,1204,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Разве можно верить грекам?",0,1205,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Гей, рабы, цепей сюда!",1,1205,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Пусть теперь рабы из храма пленных выведут нам.",0,1206,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Да.",1,1206,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Пусть им головы закроют.",0,1207,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Чтоб лучей не осквернить?",1,1207,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Да пошли со мною свиту.",0,1208,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["dir","указывая на часть свиты"],["v","Можешь этих уводить…",1,1208,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А гонца пошлешь ты в город…",0,1209,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Вести важные нашлись?",1,1209,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Чтоб домов не покидали…",0,1210,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","И от скверны береглись?",1,1210,0,1],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Разве ж долго заразиться?",0,1211,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["dir","рабу"],["v","Так ты им и передашь…",1,1211,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","И смотреть на них опасно…",0,1212,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Как хранишь ты город наш!..",1,1212,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Я храню друзей, державный…",0,1213,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Про меня ты говоришь?",1,1213,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","И про дом твой…",0,1214,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","О, недаром город целый ты дивишь.",1,1214,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Сам у храма оставайся.",0,1215,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Или дело мне нашли?",1,1215,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ты чертог огнем очистишь…",0,1216,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Чтобы в чистый ты вошла?",1,1216,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","А когда аргосцы выйдут…",0,1217,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Как тогда мне, дева, быть?",1,1217,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Ты глаза плащом прикроешь.",0,1218,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Чтобы скверны не добыть.",1,1218,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Если я промедлю долго…",0,1219,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Иль какой положишь срок?",1,1219,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Не дивись…",0,1220,0,1],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Ты с делом божьим не спеши, чтоб вышел прок.",0,1220,0,0],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Удалось бы очищенье!",0,1221,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Я с тобой о том молюсь.",1,1221,0,0],["sd","В течение последней части беседы часть слуг ушла, кто в храм, кто на луг, прилегающий к нему, кто в дом. При окончании из храма показывается процессия: ведут <span class=\"ch\" data-ch=\"orest\">Ореста</span> и <span class=\"ch\" data-ch=\"pilad\">Пилада</span> в наручниках с покрытыми головами, гонят телят, ягнят с луга, несут серные факелы. Во время прохождения процессии <span class=\"ch\" data-ch=\"foant\">Фоант</span> покрывает лицо плащом."],["sp","<span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>"],["v","Но постой, уже из дома осужденные выходят,",0,1222,0,0],["v","Ризы новые рабыни мне несут… телят я вижу,",0,1223,0,0],["v","И ягнят выводят, чтобы, заколов их, след убийства",0,1224,0,0],["v","С нечестивых я омыла; светят факелы; готово",0,1225,0,0],["v","Все, что нужно, чтоб очистить и гостей и изваянье…",0,1225,0,0],["v","Строго-настрого беречься от заразы горожанам",0,1226,0,0],["v","Я велю… Привратник храма, если он очистил руки,",0,1227,0,0],["v","Чтоб богам служить, идущий для свершенья брака, жены,",0,1228,0,0],["v","Отягченные плодами, бойтесь язвы и бегите.",0,1229,0,0],["v","Ты же, царственная дева, Зевса дочь и дочь Латоны,",0,1230,0,1],["v","Если я убийц омою, жертву примешь — там, где должно.",0,1230,0,0],["v","Будет чистою обитель Артемиды, мы блаженны",0,1231,0,0],["v","Тоже будем… Но о прочем умоляю — лучше смертных",0,1232,0,0],["v","Вам оно известно, боги, все и ты, богиня, видишь!",0,1233,0,0],["sd","Следует за процессией через правый проход. <span class=\"ch\" data-ch=\"foant\">Фоант</span> в сопровождении слуг, несущих горящие факелы, входит в храм через среднюю дверь."],["scene","Третий музыкальный антракт","s16",4,16],["sp","Хор"],["str","Строфа"],["v","О славный сын Латоны,",0,1234,0,0],["v","Не ты ли, златокудрый,",0,1235,0,0],["v","Делосские ущелья",0,1235,0,0],["v","Обогатил плодами?",0,1236,0,0],["v","Не ты ль кифарой славен,",0,1237,0,0],["v","Не ты ль и сердце тешишь",0,1238,0,0],["v","Стрельбой из лука, бог?",0,1239,0,0],["v","Тебя с утесов влажных",0,1240,0,1],["v","Детенышем, едва",0,1240,0,0],["v","Покинув ложе муки,",0,1241,0,0],["v","Родимая умчала",0,1242,0,0],["v","К Парнасской выси Вакха,",0,1243,0,0],["v","Где шумны ликованья",0,1243,0,0],["v","И где потоки бурны;",0,1244,0,0],["v","И там, где, отливаясь",0,1245,0,0],["v","Своей спиною пестрой,",0,1246,1,0],["v","Под лавром густолиственным",0,1246,0,0],["v","Вещания Фемиды",0,1247,1,0],["v","Стерег дракон чудовищный?",0,1248,0,0],["v","Еще дитя, еще",0,1249,1,0],["v","Ты, на руках у матери",0,1250,0,1],["v","Резвяся, змея-сторожа",0,1250,0,0],["v","Убил и на златом с тех пор",0,1251,0,0],["v","Божественном треножнике",0,1252,0,0],["v","Воссел, неложный бог!",0,1253,1,0],["v","Из глубины святилища",0,1254,0,0],["v","Вещанья роду смертному",0,1255,0,0],["v","Ты раздаешь. Близ вод",0,1256,1,0],["v","Кастальских твой чертог стоит,",0,1257,0,0],["v","Земли средина здесь.",0,1258,1,0],["str","Антистрофа"],["v","С тех пор, как сын Латоны",0,1259,0,0],["v","Божественных вещаний,",0,1260,0,1],["v","Землею затаенных,",0,1260,0,0],["v","Лишить дерзнул Фемиду,",0,1261,0,0],["v","Те сонные виденья",0,1262,0,0],["v","Земля сама рождает:",0,1263,0,0],["v","Что было, быть чему,",0,1263,0,0],["v","Она в пещерах темных",0,1264,0,0],["v","Гадателям в ночи",0,1265,0,0],["v","Показывает спящим",0,1266,0,0],["v","Из ненависти к Фебу.",0,1266,0,0],["v","Зачем отнять дерзнул он",0,1267,0,0],["v","У дочери оракул…",0,1268,0,0],["v","И быстрою стопою царь",0,1269,0,0],["v","Достиг Олимпа выси,",0,1270,1,1],["v","Рукою детской Зевсов трон",0,1270,0,0],["v","Обвил он, умоляя,",0,1271,1,0],["v","Чтоб из чертога Пифии",0,1272,0,0],["v","Был изгнан гнев и страх.",0,1273,1,0],["v","И, улыбаясь смелости",0,1273,0,0],["v","И жажде храма пышного,",0,1274,0,0],["v","Царь кудрями встряхнул Зевес:",0,1275,0,0],["v","Вещания ночные он",0,1276,0,0],["v","Рассеял — больше нет",0,1276,1,0],["v","Забвенья вопрошающим",0,1277,0,0],["v","Земные силы темные,",0,1278,0,0],["v","И Локсий вновь приял",0,1279,1,0],["v","Почет средь храма людного,",0,1280,0,1],["v","А человек гадающий",0,1281,1,0],["v","Уверенность обрел.",0,1282,1,0],["act","Действие четвертое","a5","IV"],["scene","Явление десятое","s17",5,17],["v","Вестник со стороны моря, смущенный и торопливый.",0,1283,0,0],["sp","Вестник"],["v","Вы, алтаря служители и храма",0,1284,0,0],["v","Хранители, скажите мне, где царь.",0,1285,0,0],["v","Царя страны зову я: эти двери",0,1286,0,0],["v","Надежные пусть выпустят царя!",0,1287,0,0],["sp","Корифей"],["v","Коли спросить позволишь, в чем же дело?",0,1288,0,0],["sp","Вестник"],["v","Их нет… Ушли те юноши… их дочь",0,1289,0,0],["v","Атридова спасла… Ее искусство…",0,1290,0,1],["v","Бежали на аргосском корабле,",0,1291,0,0],["v","И наш кумир священный там запрятан.",0,1292,0,0],["sp","Корифей"],["v","Не может быть!.. Но тот, о ком у нас",0,1293,0,0],["v","Ты спрашивал, не здесь, он храм покинул.",0,1294,0,0],["sp","Вестник"],["v","Но где же он? Царь должен все узнать.",0,1295,0,0],["sp","Корифей"],["v","Я этого не знаю, но не медли:",0,1296,0,0],["v","Беги за ним, чтоб вести передать.",0,1297,0,0],["sp","Вестник"],["v","О женщины! Как род ваш вероломен!..",0,1298,0,0],["v","Не скроетесь, участницы… О нет!..",0,1299,0,0],["sp","Корифей"],["v","Иль бредишь ты? При чем же мы в побеге?",0,1300,0,1],["v","Царя ищи… он во дворце… не здесь.",0,1300,0,0],["sp","Вестник"],["v","Пусть это мне кто скажет повернее:",0,1301,0,0],["v","Я должен знать: ушел он или нет…",0,1302,0,0],["sd","(Кричит и стучится в дверь.)"],["v","Оге!.. долой запоры… Там… за дверью!",0,1303,0,0],["v","Скажи царю, что вестник прибежал",0,1303,0,0],["v","И бед ему приносит целый ворох…",0,1304,0,0],["scene","Явление одиннадцатое","s18",5,18],["v","Те же и <span class=\"ch\" data-ch=\"foant\">Фоант</span> из средней двери храма.",0,1305,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Святилище богини кто дерзнул",0,1306,0,0],["v","Ударами неистово и криком",0,1306,0,0],["v","Тревожить? Кто подъемлет этот шум?",0,1307,0,0],["sp","Вестник"],["v","О, горе мне…",0,1308,0,0],["sd","(Указывает на хор.)"],["v","Вот эти мне сказали, что ушел",0,1309,0,0],["v","Из храма ты. Тебя я здесь не чаял…",0,1310,0,1],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","А им корысть была какая лгать?",0,1310,0,0],["sp","Вестник"],["v","Об них потом. Тут дело поважнее",0,1311,0,0],["v","И спешное. Юница, что алтарь",0,1312,0,0],["v","Хранила наш, пожалуй, уж далеко…",0,1313,0,0],["v","Уехала с аргосцами, украв",0,1314,0,0],["v","Священное богини изваянье:",0,1315,0,0],["v","И весь обряд одним обманом был…",0,1316,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Что говоришь? Злой дух в нее вошел?",0,1317,0,0],["sp","Вестник"],["v","Здесь был <span class=\"ch\" data-ch=\"orest\">Орест</span>… вот подивись чему.",0,1318,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Какой <span class=\"ch\" data-ch=\"orest\">Орест</span>? Рожденный Тиндаридой?",0,1319,0,0],["sp","Вестник"],["v","Для алтаря назначенный <span class=\"ch\" data-ch=\"orest\">Орест</span>…",0,1320,0,1],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","О, диво див… Меж чудесами чудо…",0,1321,0,0],["sp","Вестник"],["v","От дела все ж не отвлекайся, царь,",0,1322,0,0],["v","И, выслушав рассказ мой, обсуди,",0,1323,0,0],["v","Как изловить обманщиков сподручней…",0,1324,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Отлично, да. От нашего ж копья",0,1325,0,0],["v","Не так-то им легко уплыть, надеюсь.",0,1326,0,0],["sp","Вестник"],["v","Когда скалы приморской мы достигли,",0,1327,0,0],["v","Где был корабль <span class=\"ch\" data-ch=\"orest\">Орестов</span> затаен,",0,1328,0,0],["v","Атрида дочь остановила знаком",0,1330,0,1],["v","Нас, посланных, чтоб узников стеречь:",0,1330,0,0],["v","Готовилась, ты видишь ли, она",0,1331,0,0],["v","Огонь возжечь таинственный, к обряду",0,1332,0,0],["v","Священному сбираясь приступить.",0,1333,0,0],["v","И вот из рук рабов оковы взявши,",0,1333,0,0],["v","За пленными несет их. Подозренье",0,1334,0,0],["v","Уж было в нас, но спорить мы не смели..",0,1335,0,0],["v","Затем она, чтоб действия ее",0,1336,0,0],["v","Казались нам обрядом, завопила.",0,1336,0,0],["v","Нам варварский послышался напев,",0,1337,0,0],["v","И будто их, колдуя, омывает…",0,1338,0,0],["v","И долго мы крепились… все же страх",0,1339,0,0],["v","В конце концов нас донял. Ну как гости,",0,1340,0,1],["v","Оковы перебив, ее убьют…",0,1340,0,0],["v","И скроются… околдовал нас ужас:",0,1341,0,0],["v","И молча мы сидели… но всему",0,1342,0,0],["v","Конец бывает… и, не сговорившись,",0,1343,0,0],["v","Все, как один, мы кинулись к царевне…",0,1344,0,0],["v","И что же мы увидели? Сперва",0,1345,0,0],["v","Лишь корабля аргосского контуры,",0,1345,0,0],["v","Потом гребцов… и с веслами в руках",0,1346,0,0],["v","Их пятьдесят там было… — под конец же",0,1347,0,0],["v","Их, пленников, но только без оков.",0,1348,0,0],["v","В движении все было там: причальный",0,1349,0,0],["v","Те на корме канат слагали, те",0,1350,0,1],["v","Тянули вверх из моря якорь, — сходни",0,1351,0,0],["v","Для юношей спускали там поспешно.",0,1352,0,0],["v","Открыв обман, чиниться больше мы",0,1353,0,0],["v","С гречанкою не стали… Кто девицу",0,1354,0,0],["v","Старается отнять у них, а кто",0,1355,0,0],["v","Стащить канат иль вынуть руль, искусно",0,1356,0,0],["v","Прилаженный к корме. И языки",0,1357,0,0],["v","Работали при этом: \"Кто ж дозволил",0,1358,0,0],["v","Вам увозить и жрицу и кумир?",0,1359,0,0],["v","И кто ты, муж?« А он в ответ: »<span class=\"ch\" data-ch=\"orest\">Ореста</span>",0,1360,0,1],["v","Вы видите: я брат ее, и дети",0,1360,0,0],["v","Атрида мы, коль ты желаешь знать.",0,1361,0,0],["v","Погибшею для дома Танталидов",0,1362,0,0],["v","Считал сестру <span class=\"ch\" data-ch=\"orest\">Орест</span>, но он нашел",0,1362,0,0],["v","Ее у вас и взять имеет право\".",0,1363,0,0],["v","Но в девушку вцепились мы тогда",0,1364,0,0],["v","Еще дружнее, мы силою старались",0,1365,0,0],["v","Ее вернуть. Ты видишь на моих",0,1365,0,0],["v","Щеках следы ударов тяжких, царь…",0,1366,0,0],["v","Оружия аргосцы не имели,",0,1367,0,0],["v","И не было у нас его. Кулак",0,1367,0,0],["v","Там раздавал удары, ноги также",0,1368,0,0],["v","Они пускали в дело: то в живот,",0,1369,0,0],["v","То в бок нога аргосца попадала,",0,1370,0,1],["v","А сцепимся бороться мы, и вмиг",0,1371,0,0],["v","Все тело измолотят нам. Печатью",0,1372,0,0],["v","Отмечены жестокой, на утес",0,1373,0,0],["v","Взобрались мы — кому проломан череп,",0,1374,0,0],["v","Кому в глаза попало. С высоты",0,1375,0,0],["v","Сражаться нам сподручней было. Камни",0,1376,0,0],["v","Летели на корабль их. Но стрелки,",0,1377,0,0],["v","На их корме стоявшие, не долго",0,1378,0,0],["v","Нам выдержать давали. Вот волна",0,1379,0,0],["v","К земле ладью прибила — видим: дева",0,1380,0,1],["v","Ступить боится в воду, а <span class=\"ch\" data-ch=\"orest\">Орест</span>,",0,1380,0,0],["v","На левое плечо ее поднявши,",0,1381,0,0],["v","Шагает прямо в волны, вот по сходням",0,1382,0,0],["v","Взбирается и в корабельный трюм",0,1383,0,0],["v","Девицу он спускает, а за нею",0,1384,0,0],["v","И дар небес, богини изваянье.",0,1385,0,0],["v","И голос мы услышали, — он шел",0,1385,0,0],["v","Из корабля: \"За весла, мореходы!",0,1386,0,0],["v","Их лопасти покройте пеной белой,",0,1387,0,0],["v","Добыча здесь — и этот лютый путь",0,1388,0,0],["v","Недаром нам открыли Симплегады\".",0,1389,0,0],["v","Отрадный вздох гребцов ответом был,",0,1390,0,1],["v","Ударили по влаге… и покуда",0,1390,0,0],["v","Не выходил из гавани корабль,",0,1391,0,0],["v","Он двигался; но лишь ее предела",0,1392,0,0],["v","Коснулся он, напав, могучий вал",0,1392,0,0],["v","Загородил пловцам дорогу, ветер",0,1393,0,0],["v","Назад ладью крылатую повлек,",0,1394,0,0],["v","И хоть гребцы ее, с волнами споря,",0,1395,0,0],["v","На весла налегали, но прибой",0,1395,0,0],["v","Их возвращал к земле. Тогда молиться",0,1396,0,0],["v","Вот начала Агамемнона дочь:",0,1397,0,0],["v","И так она молилась: \"Дочь Латоны,",0,1397,0,0],["v","Спаси меня, ты жрицу алтарей",0,1398,0,0],["v","Своих перенеси в Элладу, дева,",0,1399,0,0],["v","От варварской земли подальше этой.",0,1400,0,1],["v","А воровства ты мне в вину не ставь,",0,1400,0,0],["v","Коли тебе твой дивен брат, иль дивно,",0,1401,0,0],["v","Что я люблю <span class=\"ch\" data-ch=\"orest\">Ореста</span>\". Моряки",0,1402,0,0],["v","Ее мольбу венчали кликом. Руки",0,1403,0,0],["v","Обнажены до самого плеча,",0,1404,0,0],["v","И движутся с двойною силой весла,",0,1405,0,0],["v","Покорные приказу, и пеан",0,1406,0,0],["v","Звучит из уст… Но нет… Скала все ближе,",0,1407,0,0],["v","Один из наших подле уж, другой",0,1408,0,0],["v","Их на канате тянет… Тут немедля",0,1409,0,0],["v","Я с вестию к державному… Спеши",0,1410,0,1],["v","С арканами, владыка, и с цепями.",0,1411,0,0],["v","Коль ветер не утихнет, для гостей",0,1412,0,0],["v","Надежды нет. А повелитель моря,",0,1413,0,0],["v","Пергама страж, могучий Посейдон,",0,1414,0,0],["v","Враждебный Пелопидам, не откажет<a class=\"nr\" href=\"#n-k44\" data-n=\"k44\" aria-label=\"Примечание 44\">44</a>",0,1415,0,0],["v","<span class=\"ch\" data-ch=\"orest\">Ореста</span> нам отважного предать",0,1416,0,0],["v","С сестрой его, которая забыла,",0,1417,0,0],["v","Что милостью богини спасена!",0,1418,0,0],["sp","Корифей"],["v","Несчастная <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>! Иго",0,1420,0,1],["v","Здесь ждет тебя — погибли ты и брат!",0,1420,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","О, жители таврического края,",0,1421,0,0],["v","Что медлите? Уздайте лошадей…",0,1422,0,0],["v","На брег морской, живее: там остатки",0,1423,0,0],["v","Аргосского найдете корабля",0,1424,0,0],["v","И, с помощью богини, нечестивцев",0,1425,0,0],["v","Перехватить успеете. Ладьи",0,1426,0,0],["v","Другие пусть спускают. Кто по волнам,",0,1427,0,0],["v","Кто посуху верхами поспешим",0,1428,0,0],["v","И, уловив аргосцев, в море с кручи",0,1429,0,0],["v","Иль на кол их… Не скроетесь и вы,",0,1430,0,1],["v","Потатчицы изменников: примерно",0,1408,0,0],["v","Я накажу вас, жены, дайте срок!",0,1386,0,0],["v","Сейчас меня другая ждет забота",0,1364,0,0],["v","И спешная — минуты на счету.",0,1341,0,0],["v","Вокруг начинается суета.",0,1319,0,0],["act","Исход","a6",""],["scene","Явление двенадцатое","s19",6,19],["v","Над говорящими на альтане показывается Афина.",0,1297,0,0],["sp","Афина"],["v","Куда ж ты, царь? Куда стопы направил,",0,1274,0,0],["v","О царь <span class=\"ch\" data-ch=\"foant\">Фоант</span>? Внемли словам моим.<a class=\"nr\" href=\"#n-k43\" data-n=\"k43\" aria-label=\"Примечание 43\">43</a>",0,1252,0,0],["v","Афина я. Останови погоню,",0,1230,0,0],["v","Дружин твоих поток останови.<a class=\"nr\" href=\"#n-k42\" data-n=\"k42\" aria-label=\"Примечание 42\">42</a>",0,1207,0,0],["v","Вещаниям покорный Аполлона,",0,1185,0,0],["v","<span class=\"ch\" data-ch=\"orest\">Орест</span> сюда явился: Евменид",0,1163,0,0],["v","Он злобою гоним и должен, в Аргос",0,1140,0,1],["v","Сестру свою доставив, отвезти",0,1141,0,0],["v","Священное в мой город изваянье —",0,1142,0,0],["v","То мук его снедающих предел.",0,1143,0,0],["v","Вот речь моя тебе: <span class=\"ch\" data-ch=\"orest\">Ореста</span> думал",0,1144,0,0],["v","Ты захватить под бурей — Посейдон",0,1145,0,0],["v","Хребет морской в угоду мне разгладил, —",0,1146,0,0],["v","И Пелопид далеко. Ты, Орест,",0,1147,0,0],["v","Хоть нет тебя перед лицом богини,",0,1148,0,0],["v","Но все ж меня послушай. Ты сестру",0,1149,0,0],["v","И статую вези. Когда же в город",0,1150,0,0],["v","Прибудешь мой ты крепкозданный, там",0,1151,0,0],["v","Есть место, царь: Кекроповых пределов",0,1152,0,0],["v","Касается оно, а подле мыс<a class=\"nr\" href=\"#n-k45\" data-n=\"k45\" aria-label=\"Примечание 45\">45</a>",0,1450,0,1],["v","Каристии открылся. Много свято",0,1450,0,0],["v","И Галами в устах оно слывет.",0,1451,0,0],["v","Построив храм, там девы изваянье",0,1452,0,0],["v","Ты водрузишь. Таврическим его",0,1453,0,0],["v","Пусть нарекут в воспоминанье муки,",0,1454,0,0],["v","Тобою здесь подъятой, и скитаний",0,1455,0,0],["v","По Греции под жалом Евменид.",0,1455,0,0],["v","На времена грядущие там песни",0,1456,0,0],["v","Таврической богине зазвучат.",0,1457,0,0],["v","Да учреди обычай, чтобы в память",0,1458,0,0],["v","О том, как был убийца искуплен,",0,1459,0,0],["v","До шеи меч у них жреца касался",0,1460,0,1],["v","И кровь пускал для вида, сердце теша",0,1461,0,0],["v","Богинино. <span class=\"ch\" data-ch=\"ifigeniya\">Ифигения</span>, ты",0,1462,0,0],["v","Ключи хранить от лестницы Бравронской",0,1463,0,0],["v","По моему велению отныне",0,1464,0,0],["v","Назначена. Там и лежать тебе,",0,1465,0,0],["v","Когда умрешь. Да ублажают деву",0,1466,0,0],["v","Одежды жен, скончавшихся в родах.",0,1467,0,0],["sd","(<span class=\"ch\" data-ch=\"foant\">Фоанту</span>.)"],["v","Гречанок ты, Фоант, освободи,",0,1468,0,0],["v","Домой отправь их… Ты ж, аргосец, жизнью<a class=\"nr\" href=\"#n-k46\" data-n=\"k46\" aria-label=\"Примечание 46\">46</a>",0,1470,0,1],["v","И раньше был обязан мне: в твою",0,1470,0,0],["v","Склонила я решенье пользу, помнишь,",0,1471,0,0],["v","Когда твои считали черепки",0,1471,0,0],["v","Там, на холме Ареевом, и было",0,1472,0,0],["v","Их поровну. Блюдите же отныне",0,1472,0,0],["v","Такой закон: коль столько ж голосов",0,1473,0,0],["v","За да, как и за нет, то муж оправдан.",0,1474,0,0],["v","Ты отдаляй, Орест, свою сестру",0,1474,0,0],["v","От этого предела, ты ж, Фоант,",0,1475,0,0],["v","Смири свой гнев, несправедливо пылкий.",0,1475,0,0],["sp","<span class=\"ch\" data-ch=\"foant\">Фоант</span>"],["v","Царица, о Афина, речи божьей",0,1476,0,0],["v","Коль человек, внимая, не покорен, —",0,1477,0,0],["v","Безумец он. Нет, на <span class=\"ch\" data-ch=\"orest\">Ореста</span> я",0,1477,0,0],["v","За статую, им взятую, и жрицу,",0,1478,0,0],["v","Его сестру, уж гнева не держу.",0,1478,0,0],["v","Прилично ли против богов могучих",0,1479,0,0],["v","Бороться нам? Пускай домой они",0,1480,0,1],["v","Плывут с их изваянием, и счастье",0,1480,0,0],["v","Венчает там богини новый храм,",0,1481,0,0],["v","В Элладу я блаженную и этих",0,1482,0,0],["v","Отправить жен готов, как ты велишь,",0,1482,0,0],["v","И, если так тебе угодно, копья",0,1483,0,0],["v","Подъятые и весла я немедля",0,1484,0,0],["v","К бездействию согласен возвратить.",0,1485,0,0],["sp","Афина"],["v","Хвалю тебя, и верь: не только люди, —",0,1485,0,0],["v","Нужде и бог покорен. Ты, дыханье",0,1486,0,0],["v","Ветров, привей <span class=\"ch\" data-ch=\"orest\">Ореста</span> в город мой…",0,1487,0,0],["v","Сопровождать туда же изваянье",0,1487,0,0],["v","Моей сестры теперь и я иду.",0,1488,0,0],["sd","(Исчезает.)"],["v","<span class=\"ch\" data-ch=\"foant\">Фоант</span> уходит во дворец.",0,1489,0,0],["sp","Корифей"],["v","О, путь вам счастливый!",0,1490,0,1],["v","Над вами зарей благодатной",0,1491,0,0],["v","Спасенье сияет.",0,1492,2,0],["sd","(Вслед Афине.)"],["v","Тебе ж, о Паллада, хвала:",0,1493,0,0],["v","Ты смертным защита,",0,1494,0,0],["v","В богах почтена ты.",0,1495,0,0],["v","Словам покорны твоим,",0,1496,0,0],["v","Твои мы исполним веленья…",0,1497,0,0],["v","Нежданная сладостна весть.",0,1498,0,0],["sp","Хор"],["dir","покидая орхестру"],["v","Благовонной короной своей<a class=\"nr\" href=\"#n-k47\" data-n=\"k47\" aria-label=\"Примечание 47\">47</a>",0,1499,0,0],["v","Увенчай поэта, победа,",0,1500,0,0],["v","И не раз, и не два, и не три",0,1501,0,0],["v","Увей ему белые кудри.",0,1502,0,0],["h1","Комментарий","comm"],["p","Наиболее вероятной датой постановки этой трагедии следует признать 414 г.: относящаяся к 412 г. «Елена» во многом повторяет ситуации «Ифигении», большой успех которой, видимо, побудил Еврипида обратиться к вторичной разработке удачно найденных им сюжетных мотивов."],["p","Миф об Ифигении, привлекший внимание драматурга также в более поздней «Ифигении в Авлиде», окончательно сложился в Греции на протяжении VII-VI вв. до н. э. Наиболее ранний вариант его был зафиксирован в «Киприях» — эпической поэме начала VII в. до н. э., посвященной предыстории Троянской войны. Здесь рассказывалось, в частности, о том, как во время сбора греческого флота в беотийской гавани Авлиде Агамемнон удачным выстрелом свалил на охоте лань и стал похваляться, что такого меткого удара не могла бы нанести сама Артемида. Разгневанная богиня наслала на флот северные ветры, не только мешавшие походу под Трою, но и крушившие корабли в самой авлидской гавани. Когда через жрецов стали выяснять причину непогоды и средства ее усмирения, оказалось, что Артемида требует себе в жертву юную дочь Агамемнона, Ифигению. Девушку вызвали из Аргоса под предлогом бракосочетания с Ахиллом и закололи на алтаре Артемиды. Однако богиня, удовлетворив свое честолюбие горем отца, спасла Ифигению от жертвенного ножа; на алтаре оказалась зарезанная лань, а Ифигения была перенесена Артемидой в далекую Тавриду (нынешний Крым) и стала там жрицей в ее храме (см. ст. 6-30, 210-220, 358-377, 783-786). В этой форме миф распространился не только в Элладе, но и далеко за ее пределами: Геродот (IV, 103), сообщая о существующем у скифов в Тавриде культе богини Девы (местная параллель к греческой Артемиде), добавляет, что они называют эту богиню Ифигенией, дочерью Агамемнона."],["p","Наряду с мифом, в Аттике существовал также культ Ифигении — жрицы Артемиды; в поселении Бравроне показывали могилу Ифигении, в соседних с ним Галах Арафенидских — деревянный кумир Артемиды, доставленный якобы из Тавриды (см. ст. 1448-1469). Данные культа и мифа впервые объединил, по-видимому, Софокл в своей не дошедшей до нас трагедии «Хрис»: когда Орест, мстя за Агамемнона, убил свою мать Клитемнестру, Аполлон приказал ему, в искупление пролитой крови, пробраться в Тавриду, где по приказу местного царя Фоанта в жертву Артемиде приносили всех попавших в эти края греков (ст. 31-39), похитить там деревянную статую Артемиды и водворить ее в Элладе (ст. 82 — 92, 972 — 982). Путешествие, грозившее обернуться для Ореста гибелью, завершилось благополучно только благодаря тому, что в Тавриде Орест встретил Ифигению, которую считал давно погибшей, и с ее помощью выполнил поручение Аполлона. Вместе с ним в Грецию вернулась Ифигения, продолжая служить Артемиде на новом месте; здесь она и была похоронена."],["p","Таким образом, в мифе об Ифигении отразились напластования различных периодов общественного сознания: Артемида — первоначально зооморфная богиня, почитаемая в виде медведицы или лани, со временем становится покровительницей этих животных и мстит человеку за их убийство. Людоедские жертвоприношения, обычные в эпоху первобытной дикости, со временем начинают восприниматься как отвратительная жестокость; поэтому Ифигения не погибает у жертвенного алтаря, а обычай приносить в жертву Артемиде людей приписывается «варварам» (ср. ст. 380-390), из чьих рук Орест и должен спасти изображение богини, оскверняемой пролитием человеческой крови. Однако Еврипид и другие греческие поэты, обрабатывавшие в той или иной мере этот миф (а среди них должны быть названы, кроме автора «Киприй», также автор «Каталога женщин», приписываемого Гесиоду, Стеихор, Пиндар, Эсхил и Софокл), едва ли задумывались над его первоначальным смыслом и историей его развития; Еврипид к тому же менее всех остальных драматургов склонен был связывать себя традиционной версией. Отсюда в «Ифигении в Тавриде» появляются такие эпизоды, представляющие несомненное нововведение Еврипида, как сон Ифигении (ст. 42-58) и ее решение отправить в Аргос письмо, фигура пастуха (236 сл.) и его рассказ, в том числе о безумном кошмаре, преследующем Ореста (ст. 281-300), взаимное узнавание брата и сестры, хитрость Ифигении и обман Фоанта; только заключительный монолог Афины вводит эту «трагедию интриги» в русло старинного культа."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"],["note","k40"],["note","k41"],["note","k42"],["note","k43"],["note","k44"],["note","k45"],["note","k46"],["note","k47"]],"n":{"k1":["Ст. 1 сл. Элида","область в северо-западном Пелопоннесе; Писа — город в Элиде, недалеко от Олимпии."],"k2":["Ст. 2. …отдал дочь.","Перевод неточный. В оригинале: «Пелоп… женился на дочери Эномая» — но отнюдь не с согласия отца, которого он коварно одолел в состязании колесниц. См. ниже, ст. 191 и примеч., 823-826. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 191-193.</b> Греческий текст дошел здесь в плохой сохранности, и переводчик дает скорее пояснение, чем перевод. Чтобы добиться руки дочери Эномая (ср. ст. 1 сл.), Пелоп должен был обогнать его в состязании на колесницах; неудачливых претендентов Эномай убивал. Пелоп подкупил Миртила, возницу Эномая, который вынул болт из чеки колесницы своего господина, и таким образом Пелоп одержал победу. Впоследствии, чтобы избавиться от свидетеля своего преступления, он столкнул Миртила в море.</span><!--/xn-->"],"k3":["Ст. 6. Еврип","узкий пролив между Беотией и Евбеей."],"k4":["Ст. 33. …Так названный.","Еврипид сближает имя Фоанта с глаголом thoazo — «быстро передвигаться», «летать»."],"k5":["Ст. 39. …я должна.","Между этим и следующим стихом — еще два стиха, пропущенные переводчиком: «Но я только начинаю обряд, заклание внутри храма — дело других»."],"k6":["Ст. 57. …сын в семье.","Снова в переводе Анненского пропуск ст. 58-60, которые в переводе Зелинского звучат следующим образом:<br>А те, кого я окропляю, гибнут.<br>Иль родственник намечен жертвой рока<br>И сон о нем? Но кто он? Строфий разве…<br>60 Но нет: бездетным был он в ту годину,<br>Когда меня в Авлиде убивали. Строфий — отец Пилада, фокидский царь, у которого был укрыт малолетний Орест. Еврипид специально оговаривает, что Ифигения не могла знать о существовании Пилада (ср. ст. 249, 920 сл.)."],"k7":["Ст. 74. Га… головы пришельцев…","Перевод неточный. В оригинале: «Видишь ли ты под зубцами карниза человеческие трофеи? — Да, лучшие из доспехов убитых чужеземцев. Однако надо тщательно обозреть (все остальное). — О Феб!» — и т. д."],"k8":["Ст. 82. …иль обруч, игрушка я?","Образы, не находящие подтверждения в оригинале, где сказано: «Как же достигнуть конца безумия, гоняющего меня по кругу?»"],"k9":["Ст. 98. …земли священной…","Образ, привнесенный переводчиком. Орест говорит о «меднокованых запорах», устройство которых пришельцам неизвестно."],"k10":["Ст. 123-235","Еще один (после «Гекубы») пример необычного построения парода: симметричные строфы вовсе не используются, и парод состоит из двух астрофических партий хора, чередующихся с такими же астрофическими монодиями Ифигении."],"k11":["Ст. 191-193","Греческий текст дошел здесь в плохой сохранности, и переводчик дает скорее пояснение, чем перевод. Чтобы добиться руки дочери Эномая (ср. ст. 1 сл.), Пелоп должен был обогнать его в состязании на колесницах; неудачливых претендентов Эномай убивал. Пелоп подкупил Миртила, возницу Эномая, который вынул болт из чеки колесницы своего господина, и таким образом Пелоп одержал победу. Впоследствии, чтобы избавиться от свидетеля своего преступления, он столкнул Миртила в море."],"k12":["Ст. 194-200. Гелия яркое око…","Речь идет о вражде детей Пелопа — Атрея и Фиеста. В стаде Атрея появился златорунный ягненок, и прорицатели истолковали это как знамение, дающее Атрею право на царский престол в Аргосе. Фиест, соблазнив жену Атрея Аэропу, выкрал при ее помощи златорунного ягненка и предъявил его в народном собрании, претендуя на царскую власть. Тогда Зевс по просьбе Атрея послал новое знамение, подтверждающее его права: солнце изменило свой прежний путь и стало передвигаться с запада на восток."],"k13":["Ст. 208. Парки","в римской мифологии богини судьбы. В оригинале, конечно, стоят греческие Мойры."],"k14":["Ст. 252. Но как вы их увидели…","Здесь, как и неоднократно в дальнейшем (ст. 750-752, 818-820, 920,932-934, 1033 сл., 1039 сл., 1163 сл., 1177-1186, 1196-1202), переводчик нарушает закон однострочной стихомифии."],"k15":["Ст. 267. …демоны таятся.","Демоны — в греческом значении слова, т. е. «божества»."],"k16":["Ст. 270. Левкотея и Палемон","морские божества (см. примеч. к «Медее», ст. 1284). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 1284 сл. Ино.</b> супруга орхоменского царя Афаманта, взяла на воспитание младенца Диониса, рожденного ее сестрой Семелой от Зевса; за это ревнивая Гера наслала на Ино припадок безумия, во время которого она убила одного из своих сыновей, а другой, спасаясь от матери, бросился в море; Ино последовала за ним. В воде мать и сын превратились в морские божества Левкотею и Палемона (см.: «Ифигения в Тавриде», ст. 270 сл.}. Здесь, однако, Еврипид приписывает Ино убийство обоих детей и опускает вторую часть мифа.</span><!--/xn-->"],"k17":["Ст. 276. …и осмеял святошу…","Акценты оригинала переставлены местами. Во-первых, там нет никакого «святоши» — слово это явно не подходит к человеку, искренне верящему в божественное происхождение пришельцев. Во-вторых, «осмеявший» назван «пустым, дерзким в беззаконии» человеком."],"k18":["Ст. 393. Жало аргосской осы","овод, терзавший Ио."],"k19":["Ст. 398-401","Хор гадает, откуда прибыли чужеземцы: из Спарты (где текут светлые воды Еврота) или из Фив (от священных волн Диркеи — см. примеч. к «Ипполиту», ст. 556). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Ипполит», Ст. 556. Диркея (правильнее Дирка).</b> источник вблизи Фив.</span><!--/xn-->"],"k20":["Ст. 421-438. Скалистые ворота","Боспор Фракийский (нынешний Босфор); Финеевы утесы — скалистая полоса на черноморском побережье Фракии, где в г. Салмидесе царствовал некогда легендарный Финей. Хор рисует путь греческих мореходов, для которых Таврида лежала на северо-востоке; добирались до нее вдоль западного, а затем северного побережья Черного моря. По пути они должны были миновать и остров Белый (см. примеч. к «Андромахе», ст. 1260-1262), расположенный в устье Дуная. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Андромаха», Ст. 1260-1262.</b> …на Белом берегу его чертог… — Несохранившаяся эпическая поэма «Эфиопида» повествовала, что Ахилл после смерти был перенесен Фетидой на остров Белый в Черном море (теперешний о. Фидониси) — вариант сказания о блаженной стране, где после земной смерти ведут безмятежную жизнь великие герои (ср. «Труды и Дни» Гесиода, ст. 168-173).</span><!--/xn-->"],"k21":["Ст. 512-513","Порядок стихов, предложенный издателями XIX в. Бэдхэмом и Кирхгофом."],"k22":["Ст. 530","В оригинале: «Спрашивай, если хочешь; я скажу». Источник перевода Анненского непонятен."],"k23":["Ст. 531-533. Хвала богине!..","Ифигения рада известию о смерти Калханта, так как именно он потребовал ее жертвоприношения в Авлиде. Тот же мотив, возможно, в «Илиаде» (I, 106-108)."],"k24":["Ст. 585. Он понимал…","Пропущена важная мысль: «Что не моя рука его убивает»."],"k25":["Ст. 589. …направив в Аргос.","Тот же случай. В оригинале: «Чтобы он передал его кому-нибудь из моих родных» (590)."],"k26":["Ст. 602. …не позволяет совесть…","См.: «Медея», примеч. к ст. 1054. Перевод оригинала: «Несправедливо, чтобы я его гибелью доставил тебе удовольствие, а сам избежал беды». <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 1054. …совесть… не позволяет….</b> В оригинале речь идет не о совести (это понятие только появляется в V в. и встречается у Еврипида еще редко), а о тех, «кому не подобает присутствовать» при этом жертвоприношении.</span><!--/xn-->"],"k27":["Ст. 620","Перевод, далекий от оригинала, где сказано: «Но это неизбежность, которой я должна подчиняться»."],"k28":["Ст. 651-653","Перевод маловразумительный. В оригинале хор сначала обращается к Пиладу («О безотрадный путь!»), потом к Оресту («Увы, увы, ты погиб! Увы, увы, кто из вас более несчастен?»)."],"k29":["Ст. 679. …Не скажет чернь…","В оригинале: «многим покажется, а негодных — много»."],"k30":["Ст. 681. …на трон замыслил твой…","Пилад боится, что в случае гибели Ореста его заподозрят в стремлении овладеть престолом аргосских царей, переходящим к нему как к мужу Электры."],"k31":["Ст. 702. …насыпь могилу мне…","Умершему в чужих краях или пропавшему без вести на родине воздвигали так называемый кенотаф — пустую гробницу; предполагалось, что его тень только тогда будет допущена в загробный мир, когда у нее будет пристанище на земле."],"k32":["Ст. 703. …и локоном почтит.","После этого стиха переводчиком пропущены еще два:<br>Ты ей скажи, что от руки погиб я<br>Аргивянки, на алтаре заклан.<br>(Перевод Ф. Ф. Зелинского)"],"k33":["Ст. 780. О, боги…","В распределении этой и следующей реплики Ореста рукописи колеблются между Орестом и Пиладом."],"k34":["Ст. 804. Навплия","город и гавань в Арголиде (нынешний Навплион)."],"k35":["Ст. 845. Очаг Киклопов","то есть Микены, чьи стены были, по преданию, сложены Циклопами."],"k36":["Ст. 917. …по матери Атреевич…","Строфий (см. примеч. к ст. 60) был женат на Анаксибии, сестре Агамемнона и Менелая. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 57. …сын в семье..</b> Снова в переводе Анненского пропуск ст. 58-60, которые в переводе Зелинского звучат следующим образом:<br>А те, кого я окропляю, гибнут.<br>Иль родственник намечен жертвой рока<br>И сон о нем? Но кто он? Строфий разве…<br>60 Но нет: бездетным был он в ту годину,<br>Когда меня в Авлиде убивали. Строфий — отец Пилада, фокидский царь, у которого был укрыт малолетний Орест. Еврипид специально оговаривает, что Ифигения не могла знать о существовании Пилада (ср. ст. 249, 920 сл.).</span><!--/xn-->"],"k37":["Ст. 940-969","История Ореста излагается здесь в основном по «Евменидам» Эсхила; см. особенно ст. 940-945, 959-969. Однако название Ареопага Еврипид выводит из первого суда, который якобы состоялся на этом холме, над Аресом, убившим Галиррофия, сына Посейдона (иначе у Эсхила, ст. 685-690), и вводит такую деталь, как разделение Эриний на два лагеря; не признавшие решения Ареопага продолжают преследовать Ореста, без чего весь «таврический» вариант мифа не мог быть согласован с рассказом о суде в Афинах, оправдавшем Ореста."],"k38":["Ст. 960. Священный день «Вместительного кубка».","Правильнее было бы: празднество «Кружек» (Хоев), которое приходилось на второй день Анфестерий, справлявшихся в конце февраля в честь Диониса. В этот день участники празднества вступали в соревнование, кто быстрее опорожнит кружку вина объемом около трех литров. Естественно, что каждый пил при этом из отдельной кружки, а не черпал вино из общего сосуда (кратера). Происхождение же этого обычая афиняне в V в. объясняли тем, что некогда Орест, явился в Афины как раз в день празднества и их предки побоялись допустить его к общему кратеру: однако, чтобы не обидеть гостя, стали пользоваться каждый отдельной кружкой."],"k39":["Ст. 1014. …к Палладе в город крепкий…","После этих слов издатели текста предполагают лакуну; перевод Анненского с такой возможностью не считается."],"k40":["Ст. 1090-1093. Алкиона","зимородок, в которого была превращена жена трахинского царя Кеика. Элегия! — здесь: «печальные песни»."],"k41":["Ст. 1098 сл. Богиня","Артемида, которая считалась помощницей при родах. Кинфинские выси. — Хор, состоящий из пленных гречанок, тоскует по родине, вспоминая о святынях Артемиды на о. Делос."],"k42":["Ст. 1202-1221","— диалог в трохеических тетраметрах снабжен отсутствующей в оригинале рифмой."],"k43":["Ст. 1234-1283","«Дифирамбический стасим» (см. примеч. к «Гекубе», ст. 905-952), почти не связанный с содержанием трагедии. Речь идет об учреждении дельфийского прорицалища Аполлона. Первоначально здесь находился оракул Фемиды, охраняемый драконом Пифоном: убив дракона, Аполлон завладел прорицалищем. Несколько иначе этот миф излагается в так называемом гомеровском гимне к Аполлону Пифийскому (ст. 171-196) и в «Евменидах» Эсхила, ст. 1-20. В антистрофе (1259 сл.) используется, по-видимому, какая-то храмовая легенда о соперничестве Аполлона с бывшей владелицей прорицалища. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Гекуба», Ст. 905-952. Этот стасим.</b> первый в творчестве Еврипида образец повествовательной хоровой песни, напоминающей аттические дифирамбы Вакхилида. В более поздних трагедиях связь таких «дифирамбических стасимов» с основным содержанием трагедии становится еще менее прочной.</span><!--/xn-->"],"k44":["Ст. 1415-1417. …Посейдон, враждебный Пелопидам…","В «Илиаде» Посейдон, как правило, держит сторону греков (см. примеч. к «Андромахе», ст. 1009-1026), Еврипид же изображает его обычно их противником (см. «Троянки», ст. 1 сл.). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Андромаха», Ст. 1009-1026.</b> По старинному преданию, Аполлон вместе с «царем морей» Посейдоном в течение года находились в услужении у троянского царя Лаомедонта, для которого они возвели мощные крепостные стены Трои. Однако Лаомедонт не заплатил им обещанной платы, чем в «Илиаде» и объясняется нена- висть Посейдона к троянцам (XXI, 441 — 460).</span><!--/xn-->"],"k45":["Ст. 1450. Кекроповы пределы","Аттика. Мыс Каристии — горный хребет и прилегающая область на юге о. Евбеи; против них на аттическом берегу залива было расположено селение Голы (см. вступительную заметку)."],"k46":["Ст. 1470","В рукописном тексте трагедии выпало обращение Афины к Оресту, содержащее начало какого-то наставления ему."],"k47":["Ст. 1497-1499","В этих стихах, целиком повторяющихся также в заключение «Финикиянок» и «Ореста», хор, несомненно, говорит от лица самого поэта."]},"mainEnd":2300,"c":[{"id":"ifigeniya","name":"Ифигения","role":"Дочь Агамемнона, жрица Артемиды в Тавриде","intro":"Дочь, спасённая Артемидой из-под жертвенного ножа и ставшая жрицей варварского культа.","arc":"Ифигения много лет приносит в жертву чужеземцев. Сон убеждает её, что Орест умер, и она ожесточается. Но среди пленников оказывается брат; после узнавания она придумывает хитрый план бегства и обманывает царя Фоанта.","st":[{"i":91,"p":4,"l":"Пролог · явление первое","t":"Сон","d":"Рассказывает о своей судьбе и о сне, который истолковала как смерть Ореста.","c":"","k":false},{"i":542,"p":24,"l":"Действие первое · явление пятое","t":"Ожесточение","d":"Узнав о пленниках, решает: раз брат умер, жалости к эллинам больше нет.","c":"","k":false},{"i":1254,"p":55,"l":"Действие второе · явление восьмое","t":"Письмо","d":"Предлагает отпустить одного пленника с письмом в Аргос и читает его вслух — так происходит узнавание.","c":"Ход, ведущий к узнаванию.","k":true},{"i":1652,"p":72,"l":"Действие второе · Коммос","t":"Узнавание","d":"Ликует, обретя брата, и придумывает план бегства.","c":"","k":false},{"i":1939,"p":84,"l":"Действие третье · явление девятое","t":"Обман Фоанта","d":"Убеждает царя, что пленники осквернены и статую надо омыть в море.","c":"","k":true}],"gen":"Ифигения"},{"id":"orest","name":"Орест","role":"Сын Агамемнона","intro":"Матереубийца, пришедший в Тавриду за статуей Артемиды по велению Аполлона.","arc":"Орест прибывает в Тавриду, чтобы избавиться от Эриний. Его готовность умереть вместо друга и благородство в споре с Пиладом — центр второй части.","st":[{"i":173,"p":8,"l":"Пролог · явление второе","t":"Прибытие","d":"С Пиладом осматривает храм и решает ночью похитить статую.","c":"","k":false},{"i":478,"p":21,"l":"Действие первое · явление четвертое","t":"Пленён","d":"Пастух рассказывает о припадке безумия Ореста и о его пленении.","c":"","k":false},{"i":1254,"p":55,"l":"Действие второе · явление восьмое","t":"Спор с Пиладом","d":"Требует, чтобы с письмом уехал Пилад, а умер он сам.","c":"","k":true},{"i":1652,"p":72,"l":"Действие второе · Коммос","t":"Узнавание","d":"Доказывает сестре, что он Орест, вспоминая подробности родного дома.","c":"","k":false}],"gen":"Орест"},{"id":"pilad","name":"Пилад","role":"Друг Ореста","intro":"Верный друг, готовый разделить смерть.","arc":"Пилад не хочет уезжать без друга, но принимает письмо — и тем запускает узнавание.","st":[{"i":1254,"p":55,"l":"Действие второе · явление восьмое","t":"Письмо","d":"Соглашается увезти письмо и передаёт его Оресту.","c":"","k":true}],"gen":"Пилад"},{"id":"foant","name":"Фоант","role":"Царь тавров","intro":"Варварский царь, обманутый жрицей.","arc":"Фоант доверчив и благочестив; узнав о бегстве, хочет погнаться за беглецами, но его останавливает Афина.","st":[{"i":1939,"p":84,"l":"Действие третье · явление девятое","t":"Обманут","d":"Верит Ифигении и отпускает её к морю.","c":"","k":false},{"i":2299,"p":100,"l":"Исход · явление двенадцатое","t":"Покорность богине","d":"Повинуется Афине и отпускает эллинов.","c":"","k":true}]}]};
